// Generated by scripts/build-lesson-content.mjs. Do not edit by hand.
window.lessonContent = [{"path":"lessons/history/01-timeline.mdx","raw":"---\ntitle: \"从 Vibe Coding 到 Agentic Engineering\"\ndescription: \"从 2025 年开始，用双轨时间轴看懂 Coding 模型的发布，如何与 Vibe Coding、Agent、Skills 和工程实践相互推动。\"\nsection: history\norder: 1\nestimatedMinutes: 14\nprerequisites: []\noutcomes:\n  - \"区分模型发布与工具、Agent 工作方式的演进\"\n  - \"说清 Vibe Coding、Coding Agent、Skills 与 Agentic Engineering 的关系\"\n  - \"把产品热度与真正的工作方式变化区分开\"\n  - \"理解为什么能力越强，验证和权限边界越重要\"\ntags: [\"时间轴\", \"模型发布\", \"概念演进\", \"2025–2026\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst:\n  - \"DeepSeek 官方发布\"\n  - \"Anthropic Claude 与 Agent Skills 官方发布\"\n  - \"OpenAI GPT 与 Codex 官方发布\"\n  - \"Google Gemini 官方发布\"\n  - \"Z.AI GLM 与 Moonshot Kimi 官方发布\"\n  - \"OpenClaw 官方仓库\"\ndraft: false\n---\n\nimport Timeline from \"../../../components/Timeline.astro\";\n\nexport const milestones = [\n  {\n    date: \"2025 年 1 月至 2 月\",\n    model: {\n      title: \"DeepSeek-R1 与开放推理模型\",\n      concept: \"推理模型 / 开放权重 / 本地部署\",\n      summary: \"DeepSeek-R1 让更多团队看到：强推理能力不必只存在于一个封闭应用里。模型权重、API 服务与上层工具可以被拆开选择，企业也可以在自己的基础设施中提供兼容接口。\",\n      impact: \"Coding Agent 开始更像一个可替换模型的工作台。保留同一套 OpenCode 工作方式时，管理员可以切换后端模型。\",\n      question: \"开放权重或本地部署不自动等于安全。模型能力、服务权限、日志留存和数据边界仍要分别评估。\",\n      sources: [\n        { label: \"DeepSeek-R1 官方发布\", href: \"https://api-docs.deepseek.com/news/news250120/\" }\n      ]\n    },\n    agent: {\n      title: \"Vibe Coding 被命名\",\n      concept: \"自然语言编程 / Accept All / 快速原型\",\n      summary: \"Andrej Karpathy 用“Vibe Coding”描述一种新体验：说出想法，运行 AI 写出的代码，看到问题后继续用语言调整。这个词捕捉到的不是新语法，而是人与代码关系的变化。\",\n      impact: \"产品、设计和运营人员第一次能直接做出可运行的软件原型。表达意图的能力，开始比记忆 API 更早产生价值。\",\n      question: \"原始描述带有“忘掉代码”的轻松意味，适合探索性项目；当软件进入生产，谁来理解风险并对结果负责？\",\n      sources: [\n        { label: \"Collins 2025 年度词\", href: \"https://www.collinsdictionary.com/de/woty\" }\n      ]\n    }\n  },\n  {\n    date: \"2025 年 2 月 24 日\",\n    model: {\n      title: \"Claude 3.7 Sonnet：推理进入 Coding 工作流\",\n      concept: \"混合推理 / 代码能力 / 长任务\",\n      summary: \"Claude 3.7 Sonnet 把即时回答与可延长的推理放在同一个模型里，并重点展示了代码任务能力。它是这一轮“让模型直接参与工程”的代表性起点。\",\n      impact: \"模型不再只生成局部代码建议，也开始更适合处理跨文件理解、修改和验证这类需要连续判断的任务。\",\n      question: \"更长的推理不会替代验收。模型输出的计划、修改和测试证据仍需要由人或可靠的自动化机制检查。\",\n      sources: [\n        { label: \"Claude 3.7 Sonnet 官方发布\", href: \"https://www.anthropic.com/news/claude-3-7-sonnet\" }\n      ]\n    },\n    agent: {\n      title: \"Claude Code 引爆终端 Agent\",\n      concept: \"Agentic Coding / 工具调用 / 自动测试\",\n      summary: \"Claude Code 的研究预览把 Agent 放进终端：它能搜索仓库、编辑文件、执行命令、运行测试。工作的基本单位不再是一个函数或代码片段，而是一个带有验收条件的工程任务。\",\n      impact: \"终端成为 Agent 的通用接口。后续 OpenCode、Codex CLI、Gemini CLI 等工具都强化了“读—改—跑—查”的循环。\",\n      question: \"能执行命令意味着能造成真实影响。审批、沙箱、版本控制和最小权限开始成为日常使用的一部分。\",\n      sources: [\n        { label: \"Claude Code 官方发布\", href: \"https://www.anthropic.com/news/claude-3-7-sonnet\" }\n      ]\n    }\n  },\n  {\n    date: \"2025 年 3 月\",\n    model: {\n      title: \"Gemini 2.5 Pro：Thinking 与代码能力结合\",\n      concept: \"Thinking model / 代码 / 长上下文\",\n      summary: \"Google 将 Gemini 2.5 Pro 定义为会在回答前推理的 Thinking model，并把复杂推理和代码能力作为核心场景。\",\n      impact: \"模型厂商开始把“能否完成长链路、工具辅助的任务”作为重要能力，而不是只比较单轮聊天表现。\",\n      question: \"长上下文与推理能力能减少中断，却也可能掩盖错误假设；上下文中的资料质量仍决定结果的上限。\",\n      sources: [\n        { label: \"Gemini 2.5 Pro 官方发布\", href: \"https://blog.google/innovation-and-ai/models-and-research/google-deepmind/gemini-model-thinking-updates-march-2025/\" }\n      ]\n    },\n    agent: {\n      title: \"Manus 带火通用 AI Agent\",\n      concept: \"General Agent / 虚拟电脑 / 任务交付\",\n      summary: \"Manus 的传播让公众看到另一种 Agent：不是只回答问题，而是在独立环境中浏览网页、整理资料、生成文件并交付结果。Coding Agent 与通用 Agent 的边界开始变薄。\",\n      impact: \"人们开始按“最终交付物”而不是“回答得像不像人”评价 AI。软件开发也被放进更长的研究、设计和发布链路里。\",\n      question: \"长链路任务会累积错误。过程不可见、来源不清楚或无法回滚时，一个漂亮结果并不足以证明任务完成。\",\n      sources: [\n        { label: \"Manus 官方回顾\", href: \"https://manus.im/blog/what-we-saw-in-the-past-three-months-and-what-we-see-in-the-future\" }\n      ]\n    }\n  },\n  {\n    date: \"2025 年 4 月至 6 月\",\n    agent: {\n      title: \"Coding Agent 集体爆发\",\n      concept: \"CLI / 云端沙箱 / PR Agent\",\n      summary: \"Codex CLI 与云端 Codex、GitHub Copilot Coding Agent、Gemini CLI、OpenCode 等相继受到关注。产品形态逐渐稳定为三类：本地终端协作、云端并行任务、Issue 到 Pull Request 的后台代理。\",\n      impact: \"Agent 不再绑定某一个编辑器或模型。团队开始组合本地反馈速度、云端隔离执行和 GitHub 审查流程。\",\n      question: \"产品名称越来越多，但选型不能只看榜单。数据是否出网、能否使用企业模型、如何审查变更更值得优先比较。\",\n      sources: [\n        { label: \"Codex\", href: \"https://openai.com/index/introducing-codex/\" },\n        { label: \"Copilot Coding Agent\", href: \"https://github.blog/news-insights/product-news/github-copilot-meet-the-new-coding-agent/\" },\n        { label: \"Gemini CLI\", href: \"https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-cli-open-source-ai-agent/\" }\n      ]\n    }\n  },\n  {\n    date: \"2025 年 7 月至 8 月\",\n    model: {\n      title: \"GLM‑4.5 与 Kimi K2：开放权重转向 Agent 任务\",\n      concept: \"开源权重 / Coding / Tool use\",\n      summary: \"GLM‑4.5 将推理、代码和 Agent 任务作为一体能力发布；Kimi K2 也以工具调用和自主解决问题为重点。这两次发布让中文开放模型更直接进入 Coding Agent 的可选模型清单。\",\n      impact: \"企业可以在开源权重、兼容 API 与不同终端工具之间组合，减少工作流对单一闭源模型的绑定。\",\n      question: \"“开放”不代表部署成本低，也不代表工具调用完全兼容。推理资源、许可证、协议差异和运维能力都要先验证。\",\n      sources: [\n        { label: \"GLM‑4.5 官方发布\", href: \"https://z.ai/blog/glm-4.5\" },\n        { label: \"Kimi K2 官方项目\", href: \"https://github.com/MoonshotAI/Kimi-K2\" }\n      ]\n    },\n    agent: {\n      title: \"OpenCode：模型可替换的终端工作台\",\n      concept: \"兼容 API / 本地优先 / 工具协议\",\n      summary: \"终端型 Agent 不再只服务于一家模型。以兼容 API 为接口的工具，把模型提供方、执行环境和工程流程拆成可以分别选择的部件。\",\n      impact: \"这也解释了本教程为何以 OpenCode 与企业兼容 API 为主线：练习的是可迁移的工作流，而不是某个单一产品的按钮。\",\n      question: \"可替换不等于无差异。不同模型的上下文、工具调用和安全策略不同，切换后应重新跑关键任务与测试。\",\n      sources: [\n        { label: \"OpenCode 官方项目\", href: \"https://github.com/anomalyco/opencode\" }\n      ]\n    }\n  },\n  {\n    date: \"2025 年 10 月至 12 月\",\n    model: {\n      title: \"DeepSeek‑V3.2：面向 Agent 的开放模型继续迭代\",\n      concept: \"开放模型 / 推理优先 / Agent\",\n      summary: \"DeepSeek 在 12 月发布 V3.2。官方将其列为面向 Agent 的推理优先模型，显示开放模型的竞争重点已从一般对话扩展到工具使用和复杂任务。\",\n      impact: \"对团队而言，模型评估开始同时看推理、代码、工具调用与运行成本，而不是只看单一聊天体验。\",\n      question: \"公开发布并不能替代内部评测。涉及企业代码时，还需确认部署方式、数据流和实际任务上的稳定性。\",\n      sources: [\n        { label: \"DeepSeek 透明度中心\", href: \"https://www.deepseek.com/en/transparency/\" }\n      ]\n    },\n    agent: {\n      title: \"Agent Skills 成为新热词\",\n      concept: \"SKILL.md / 渐进加载 / 开放标准\",\n      summary: \"Agent Skills 把说明、参考资料与脚本放进一个可发现的目录。Agent 先看到名称和描述，真正需要时才读取完整内容。12 月，Skills 进一步成为跨产品的开放标准。\",\n      impact: \"关注点从“写一句万能 Prompt”转向“把团队经验变成可测试、可版本化、可共享的能力”。工作方法开始像代码一样被维护。\",\n      question: \"Skill 可能包含脚本和外部依赖。安装社区 Skill 前，必须检查它会读取什么、运行什么、连接哪里。\",\n      sources: [\n        { label: \"Agent Skills 官方介绍\", href: \"https://www.anthropic.com/engineering/equipping-agents-for-the-real-world-with-agent-skills\" }\n      ]\n    }\n  },\n  {\n    date: \"2026 年 1 月至 2 月\",\n    model: {\n      title: \"Claude Opus 4.6：更长时间的 Agentic Coding\",\n      concept: \"代码审查 / 调试 / 1M 上下文\",\n      summary: \"Anthropic 在 Claude Opus 4.6 发布中明确强调：它能更仔细地规划，在更大代码库中持续执行 Agent 任务，并改进代码审查和调试。\",\n      impact: \"闭源前沿模型的重点从“写出一段代码”进一步转向在大型工程中保持任务连续性和自我纠错。\",\n      question: \"持续执行时间越长，越需要把权限、停止条件和可回滚的中间产物设计进工作流。\",\n      sources: [\n        { label: \"Claude Opus 4.6 官方发布\", href: \"https://www.anthropic.com/news/claude-opus-4-6\" }\n      ]\n    },\n    agent: {\n      title: \"OpenClaw 与长期运行 Agent\",\n      concept: \"常驻 Agent / 持久记忆 / 消息渠道\",\n      summary: \"OpenClaw 从 Clawdbot、Moltbot 更名后迅速传播。它通过消息应用接受任务，连接浏览器、文件、邮件和日历，并能持续运行。Agent 从一次 coding session 扩展成了个人计算环境的一部分。\",\n      impact: \"Skills、记忆、定时任务和多渠道连接组合到一起，展示了“自己的 Agent”可以是什么样子。\",\n      question: \"常驻 Agent 拥有更长时间和更大权限，也更容易受到 Prompt Injection、凭证泄露和错误自动化影响。\",\n      sources: [\n        { label: \"OpenClaw 官方项目\", href: \"https://github.com/openclaw/openclaw\" }\n      ]\n    }\n  },\n  {\n    date: \"2026 年至今\",\n    model: {\n      title: \"Claude Fable 5：长周期 Coding Agent\",\n      concept: \"长任务 / 子 Agent / 自我测试\",\n      summary: \"Anthropic 将 Claude Fable 5 定位为可处理数日复杂、异步任务的第五代模型，并明确把软件工程、Claude Code 与多 Agent 协作作为主要使用场景。\",\n      impact: \"模型能力的讨论从“能不能写出来”进一步转向“能否在较少监督下持续完成大工程”，也让停止条件、审查和安全护栏变得更关键。\",\n      question: \"一个可运行数日的 Agent，何时应该自主推进，何时必须停下来等待人的审批？\",\n      sources: [\n        { label: \"Claude Fable 5 官方发布\", href: \"https://www.anthropic.com/news/claude-fable-5-mythos-5\" }\n      ]\n    },\n    agent: {\n      title: \"Multi-Agent 与 Agentic Engineering\",\n      concept: \"并行 Agent / Worktree / 自动化 / 监督\",\n      summary: \"Codex App 等产品开始让用户同时指挥多个 Agent，在隔离 worktree 中并行工作。讨论也从 Vibe Coding 走向 Agentic Engineering：不再只强调表达想法，而是强调任务拆解、约束、测试和审查。\",\n      impact: \"人的主要工作从逐行输入代码转向定义问题、设计接口、判断证据和承担最终责任。\",\n      question: \"并行并不会自动提高质量。没有清晰边界的多 Agent，只会更快地产生冲突、重复和不可审查的修改。\",\n      sources: [\n        { label: \"Codex App 官方发布\", href: \"https://openai.com/index/introducing-the-codex-app/\" }\n      ]\n    }\n  }\n];\n\nexport const modelReleases2026 = {\n  deepSeekV4: {\n    title: \"DeepSeek‑V4：兼容接口进入新一代开放模型\",\n    concept: \"V4‑Pro / V4‑Flash / OpenAI 与 Anthropic 兼容\",\n    summary: \"DeepSeek 在 4 月发布 V4，并提供 V4‑Pro 与 V4‑Flash。官方 API 同时支持 OpenAI Chat Completions 与 Anthropic 接口，模型的替换成本继续下降。\",\n    impact: \"对终端 Agent 使用者来说，模型竞争不只发生在能力榜单，也发生在是否能以较小迁移成本接入现有工作流。\",\n    question: \"协议兼容解决了接入问题，却不能保证行为一致；切换模型后，哪些关键任务必须重新评测？\",\n    sources: [\n      { label: \"DeepSeek‑V4 官方更新\", href: \"https://api-docs.deepseek.com/updates\" }\n    ]\n  },\n  glm52: {\n    title: \"GLM‑5.2：为长周期工程任务而生\",\n    concept: \"1M 上下文 / Coding Agent / MIT 开源\",\n    summary: \"Z.AI 在 6 月发布 GLM‑5.2，重点是可稳定维持长周期任务的 1M 上下文、可调节的推理强度，以及面向 Coding Agent 的能力；模型同时提供 MIT 开源许可。\",\n    impact: \"它把“长上下文”从参数竞争拉回真实工程轨迹：长任务能否持续保持代码、工具调用与调试质量，才是 Agent 实用性的关键。\",\n    question: \"上下文窗口变大后，团队怎样避免把无关资料和历史错误一起带进 Agent 的长期轨迹？\",\n    sources: [\n      { label: \"GLM‑5.2 官方发布\", href: \"https://z.ai/blog/glm-5.2\" }\n    ]\n  },\n  gpt56: {\n    title: \"GPT‑5.6：模型族直接进入 Codex\",\n    concept: \"Sol / Terra / Luna / ChatGPT / Codex / API\",\n    summary: \"OpenAI 在 7 月正式发布 GPT‑5.6 系列：旗舰 Sol、均衡的 Terra 与高效的 Luna，并同时提供给 ChatGPT、Codex 和 API。\",\n    impact: \"Coding 工作流开始更明确地按任务难度、成本与所需推理强度选择模型，而不是固定使用同一个旗舰。\",\n    question: \"当同一家提供多档模型时，团队如何定义升级策略、成本上限与回归评测？\",\n    sources: [\n      { label: \"GPT‑5.6 官方发布\", href: \"https://openai.com/index/gpt-5-6/\" }\n    ]\n  },\n  kimiK3: {\n    title: \"Kimi K3：开放前沿模型走进 Kimi Code\",\n    concept: \"开放前沿 / Kimi Code / API\",\n    summary: \"Moonshot 在 7 月发布 Kimi K3，并把它提供到 Kimi、Kimi Work、Kimi Code 与 Kimi API。官方将其定位为开放前沿智能模型，也把 Coding 放进主要评测与使用场景。\",\n    impact: \"它让 2026 年的模型竞争更清楚地呈现为：闭源模型继续拉长自主任务，开放模型同时追赶代码、上下文和工具调用能力。\",\n    question: \"模型开放后的真正门槛在哪里：权重、推理资源、服务容量，还是适配工具链和安全治理的能力？\",\n    sources: [\n      { label: \"Kimi K3 官方发布\", href: \"https://www.kimi.com/blog/kimi-k3\" }\n    ]\n  }\n};\n\nexport const timelineEvents = [\n  { date: \"2025 年 1 月 20 日\", sort: \"2025-01-20\", model: milestones[0].model },\n  { date: \"2025 年 2 月 2 日\", sort: \"2025-02-02\", agent: milestones[0].agent },\n  {\n    date: \"2025 年 2 月 24 日\",\n    sort: \"2025-02-24\",\n    model: milestones[1].model,\n    agent: milestones[1].agent\n  },\n  { date: \"2025 年 3 月 5 日\", sort: \"2025-03-05\", agent: milestones[2].agent },\n  { date: \"2025 年 3 月 25 日\", sort: \"2025-03-25\", model: milestones[2].model },\n  { date: \"2025 年 5 月至 6 月\", sort: \"2025-05-15\", agent: milestones[3].agent },\n  { date: \"2025 年 7 月\", sort: \"2025-07-15\", agent: milestones[4].agent },\n  { date: \"2025 年 7 月至 8 月\", sort: \"2025-07-28\", model: milestones[4].model },\n  { date: \"2025 年 10 月至 12 月\", sort: \"2025-10-16\", agent: milestones[5].agent },\n  { date: \"2025 年 12 月 1 日\", sort: \"2025-12-01\", model: milestones[5].model },\n  { date: \"2026 年 1 月至 2 月\", sort: \"2026-01-20\", agent: milestones[6].agent },\n  { date: \"2026 年 2 月 5 日\", sort: \"2026-02-05\", model: milestones[6].model },\n  { date: \"2026 年 2 月至今\", sort: \"2026-02-20\", agent: milestones[7].agent },\n  { date: \"2026 年 4 月 24 日\", sort: \"2026-04-24\", model: modelReleases2026.deepSeekV4 },\n  { date: \"2026 年 6 月 9 日\", sort: \"2026-06-09\", model: milestones[7].model },\n  { date: \"2026 年 6 月 16 日\", sort: \"2026-06-16\", model: modelReleases2026.glm52 },\n  { date: \"2026 年 7 月 9 日\", sort: \"2026-07-09\", model: modelReleases2026.gpt56 },\n  { date: \"2026 年 7 月 16 日\", sort: \"2026-07-16\", model: modelReleases2026.kimiK3 }\n];\n\n2025 年之前，AI 编程已经经历了补全、聊天和编辑器集成。但这本手册从 2025 年开始，因为这一年发生了一个更重要的变化：**模型不再只给建议，它开始在真实的软件环境里采取行动。**\n\n这条时间轴不试图记录每次模型升级，也不拿关注度当作能力证明。左侧只保留 DeepSeek、GLM、Kimi，以及 Claude、GPT、Gemini 这六个模型家族中改变 Coding 工作方式的发布；右侧保留改变工作单位、协作接口或责任边界的节点。\n\n<Timeline events={timelineEvents} />\n\n## Token 的流向：从聊天消耗到工程负载\n\nToken 不是生产率的同义词：它会受模型、价格、上下文长度、缓存和产品策略影响。但它能回答另一个更基础的问题：真实工作是否已经从零散对话，迁移到了需要读取代码库、调用工具并反复验证的长链路任务？公开路由数据和 Claude Code 的内部使用数据，给出了相同方向的信号。\n\n| 观察窗口 | 可核对的数据 | 它说明什么 |\n| --- | --- | --- |\n| OpenRouter 公开流量 | OpenRouter 与 a16z 对超过 **100 万亿 token** 的真实交互做了研究；编程请求的 token 占比从 2025 年初约 **11%** 升至研究期末的 **50% 以上**。编程请求的输入上下文通常超过 **20K token**。 | Coding 已经不是“偶尔让模型补一段代码”。模型正在持续读取更大的代码、文档和历史上下文，承担调试、理解与生成组成的工作负载。 |\n| Claude Code 外部真实使用 | Anthropic 对 2025 年 10 月至 2026 年 4 月约 **40 万个 session、23.5 万名用户** 的分析显示，**56%** 的 session 直接用于写代码、修复代码、测试或编排；一次用户指令平均触发约 **10 次** Claude 行动。 | Agent 的基本单位已是“给一个目标，再让它读—改—跑—查”，而不再是单次问答。 |\n| Claude Code 在 Anthropic 内部 | Anthropic 对 **20 万份** 内部 Claude Code transcript 的比较发现，连续工具调用从 **9.8** 次增至 **21.2** 次（+116%），每个 transcript 的人工轮次从 **6.2** 降至 **4.1** 次（-33%）。同一项内部调研中，员工自报 Claude 已覆盖约 **59%** 的日常工作，并带来约 **50%** 的生产率提升；这是自报结果，不应当外推为所有团队的因果结论。 | 当能力、上下文和工具链共同改进时，人不必频繁把执行拆成小指令；人的注意力可以转向目标、边界、验收与异常处理。 |\n\n数据口径并不相同：OpenRouter 是单一平台的聚合 token 流量，Anthropic 数据包含内部样本与自报调查，不能相加，也不能直接代表整个行业。但它们共同否定了一个旧印象：AI Coding 只是写得更快一点。更大的上下文、更长的执行链和更少的人工微操作，说明软件生产的**执行层**正在被重新组织。\n\n来源：[OpenRouter《State of AI》](https://openrouter.ai/state-of-ai)、[Anthropic：Claude Code 的实际使用](https://www.anthropic.com/research/claude-code-expertise)、[Anthropic：AI 如何改变内部工作](https://www.anthropic.com/research/how-ai-is-transforming-work-at-anthropic)。\n\n## 飞轮已经转起来了，工作单位也在变大\n\n> **观点：飞轮已经转起来了。** 更强的模型让 Agent 能完成更长的工程任务；更长的任务产生更多真实的代码、测试、日志和使用反馈；这些反馈又让模型、工具协议、Skills 与评测更贴近生产环境。AI Coding 不再只是“更快写代码”，而是在降低尝试、验证和跨领域协作的成本，开启一次巨大的生产力提升。\n\n这个飞轮最明显的结果，是 AI 的工作单位不断变大：代码补全时代是一行代码；Vibe Coding 把它扩大为一个可见效果；Claude Code 等工具又把它扩大为一个工程任务；Skills 让一套完成任务的方法能够复用；OpenClaw 和多 Agent 产品则让任务跨越应用、设备和时间。\n\n工作单位越大，人越不可能通过“盯着每一个字符”控制质量，必须把测试、审查、权限和回滚放进同一个闭环。飞轮转得越快，越要升级控制方式：\n\n1. 在开始前写清目标、限制和验收标准；\n2. 把大任务切成可以独立验证的小任务；\n3. 让 Agent 展示计划、差异、命令和测试结果；\n4. 给高风险动作设置审批与最小权限；\n5. 用 Git、测试和日志保留回退与追溯路径。\n\n否则，被放大的也会是错误。\n\n## 从“忘掉代码”到“对结果负责”\n\nVibe Coding 的价值是真实的：它让更多人能够直接把想法做成东西。它的风险也同样真实：自然语言看起来简单，却可能隐藏模糊需求；生成速度很快，却可能让审查和理解跟不上。\n\n因此，本教程不会把 Vibe Coding 与工程纪律放在对立面。我们保留它快速探索、即时反馈的优势，再加入计划、测试、版本控制和安全边界。你可以不亲手输入每一行代码，但必须能够回答：\n\n- 这次修改要解决什么问题？\n- Agent 改了哪些文件，为什么？\n- 什么证据表明它真的可用？\n- 出错时如何回到上一个安全状态？\n- 哪些信息和权限绝不能交给它？\n\n这就是从“感觉正确”走向 Agentic Engineering 的起点。\n"},{"path":"lessons/tools/01-map.mdx","raw":"---\ntitle: \"模型地图：先看最新模型，再选工具\"\ndescription: \"以 2026 年 7 月快照认识 Claude、OpenAI、Gemini、DeepSeek、GLM 和 Kimi，再把模型接入 Agent 与企业工作流。\"\nsection: tools\norder: 1\nestimatedMinutes: 16\nprerequisites: [\"读完历史时间轴\"]\noutcomes:\n  - \"区分国外闭源服务与中国开放权重模型\"\n  - \"按能力、部署、数据和成本比较模型，而不是迷信总榜\"\n  - \"为企业 OpenAI 兼容 API 选择可验证的模型候选\"\ntags: [\"模型地图\", \"闭源模型\", \"开放权重\", \"选型\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Anthropic Claude 官方发布\", \"OpenAI API models\", \"Google Gemini model docs\", \"DeepSeek transparency\", \"Z.ai / GLM model cards\", \"Moonshot Kimi model cards\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n这门课从模型开始，但不把“最新”理解成一张永远正确的排行榜。本页是 **2026 年 7 月的模型地图快照**：模型名称、价格、上下文上限、Preview 状态和 API 别名都会变化，真正接入企业项目之前要重新核对官方文档。\n\n## 先分清两种交付方式\n\n| 类别 | 本课选取 | 常见交付方式 | 先问企业什么 |\n| --- | --- | --- | --- |\n| 国外闭源服务 | Claude、OpenAI、Gemini | 厂商 API、托管控制台、配套 Agent 产品 | 数据是否出境、保留多久、区域与合规范围是什么？ |\n| 中国开放权重模型 | DeepSeek、GLM、Kimi | 官方 API、开放权重、企业自建推理服务 | 具体模型的许可证、显存、推理引擎和运维谁负责？ |\n\n“开源模型”在口语中经常混用。更准确的说法是：**开放权重不等于所有训练数据、代码和服务条款都开放**。部署前以对应模型卡和许可证为准，不要只因为模型文件可以下载，就默认它适合商业使用。\n\n## 国外闭源三家\n\n以下是入门时需要认识的家族，不是强弱排序。每一家的版本会交替更新，选择时应使用稳定的、明确写入项目配置的模型 ID。\n\n| 家族 | 2026 年 7 月可先认识的型号 | 更适合拿来观察什么 | 企业接入时核对 |\n| --- | --- | --- | --- |\n| **Claude** | [Claude Fable 5](https://www.anthropic.com/news/claude-fable-5-mythos-5) 面向最复杂的长周期 Coding；[Claude Sonnet 5](https://www.anthropic.com/news/claude-sonnet-5) 面向规模化 Agent/Coding | 长任务、代码库理解、工具调用和持续的 Agent 工作 | API 区域、数据处理条款、上下文与用量上限、Claude Code 的权限边界 |\n| **OpenAI** | [GPT-5.6 Sol / Terra / Luna](https://developers.openai.com/api/docs/models/all)：复杂专业任务、能力/成本平衡、高吞吐三种取向 | Responses API、结构化工具调用、后台任务与多 Agent 编排 | 使用稳定模型 ID 还是别名、数据控制、速率限制、是否需要特定区域 |\n| **Gemini** | [Gemini 3.6 Flash](https://ai.google.dev/gemini-api/docs/models) 稳定高性价比；Gemini 3.5 Flash 面向持续 Agent/Coding；Gemini 3.1 Pro 仍是 Preview | 多模态输入、长上下文、Agentic Coding，以及 Stable/Preview 的生命周期差异 | Preview 是否允许生产使用、模型弃用通知、配额、输入数据的保留策略 |\n\n闭源模型的优势是开箱即用、服务商负责推理基础设施；代价是模型权重不可审计，网络、账号、数据处理和供应商变更都会成为工程约束。\n\n## 中国开放权重三家\n\n这里保留你在课程中指定的三个家族。它们通常同时提供 API 与可下载的权重，但每个版本的许可证和部署要求可能不同。\n\n| 家族 | 当前应先认识的型号 | 典型能力与形态 | 部署提醒 |\n| --- | --- | --- | --- |\n| **DeepSeek** | [DeepSeek-V4-Pro / V4-Flash](https://www.deepseek.com/en/transparency/)（可从官方 [V4 模型集合](https://huggingface.co/collections/deepseek-ai/deepseek-v4)核对版本） | 推理与 Coding 家族；同时提供 API 和开放权重版本 | 许可证以具体模型卡为准，显存、量化、vLLM/SGLang 支持要单独验证；旧的 `deepseek-chat`、`deepseek-reasoner` 别名正在退场 |\n| **GLM** | [GLM-5.2 模型卡](https://huggingface.co/zai-org/GLM-5.2)；[GLM-4.7 文档](https://docs.z.ai/guides/llm/glm-4.7)仍是 Coding Agent 的重要参考 | 长上下文、推理和终端 Agent；既可走 Z.ai API，也可按模型卡自部署 | 不要把 API 的可用型号当成可本地部署型号；核对 MIT 或其他许可证、硬件与推理引擎版本 |\n| **Kimi** | [Kimi K2.7-Code 模型卡](https://huggingface.co/moonshotai/Kimi-K2.7-Code)；[Kimi K2.5 官方仓库](https://github.com/MoonshotAI/Kimi-K2.5) | 面向 Coding Agent 的开放权重路线，支持视觉/视频与 OpenAI、Anthropic 兼容 API | K2 家族更新很快；固定版本前先看模型卡、上下文长度、`preserve_thinking` 行为和 vLLM/SGLang/KTransformers 要求 |\n\n开放权重的真正价值不只是“免费”：它让企业可以评估权重、选择推理服务商、在内网部署或做蒸馏与量化。与此同时，GPU 预算、升级责任、许可证解释和安全补丁也从供应商转移到了团队。\n\n## 用场景选候选，不做总榜\n\n| 场景 | 可以先放进评估集的候选 | 需要实测的指标 |\n| --- | --- | --- |\n| 代码库理解、长任务 Agent | Claude Opus、GPT-5.6 Sol、Gemini 3.5 Flash、DeepSeek V4-Pro、GLM-5.2、Kimi K2.7-Code | 任务完成率、工具调用是否稳定、失败后能否恢复 |\n| 高频、成本敏感的自动化 | GPT-5.6 Luna、Gemini 3.6 Flash，以及对应的开放权重 Flash/量化版本 | 首 token 延迟、吞吐、单任务总 token、并发时的错误率 |\n| 内网或专有数据 | DeepSeek、GLM、Kimi 的开放权重版本 | 最小 GPU 配置、许可证、日志是否留在内网、升级与回滚方案 |\n| 多模态需求 | Gemini 系列、Kimi K2 家族，以及企业批准的闭源视觉模型 | 图片/视频输入限制、工具调用、敏感数据脱敏效果 |\n\n这张表只是**候选集**。不要用供应商自己的“最强模型”描述代替评测。用同一批真实任务、同一套工具定义和同一套验收标准跑小型基准，才知道某个模型是否适合你的项目。\n\n## 模型、Agent、Skill 是三层\n\n| 层 | 回答的问题 | 例子 |\n| --- | --- | --- |\n| 模型 | 谁负责理解与生成？ | Claude、GPT、Gemini、DeepSeek、GLM、Kimi |\n| Agent / Harness | 谁组织上下文、调用工具、循环执行？ | OpenCode、Claude Code、Codex CLI、Kimi Code CLI |\n| Skill | 如何把上下文、步骤和验收标准封装成可复用能力？ | `SKILL.md`、团队工作流、项目规范 |\n\n同一个模型放进不同 Agent，使用体验和安全边界可能完全不同；同一个 Agent 连接不同模型，能力、速度和成本也会变化；Skill 则决定团队经验能否稳定复用。后面的课程会把模型选择落实为 `VIBE_BASE_URL`、`VIBE_API_KEY` 和 `<MODEL_ID>`，而不是把密钥写进仓库。\n\nMCP 与 Subagent 不是第四、第五种模型层。**MCP 位于 Agent 的工具连接边界**，让它访问外部工具和数据；**Subagent 位于 Agent 的任务编排内部**，让主 Agent 把一部分工作交给独立上下文处理。工具介绍为它们分别安排了 [Agent 与 Subagent](/vibe_coding_guide/tools/agent-subagents/)和 [MCP](/vibe_coding_guide/tools/mcp/)独立章节。\n\n## 两种常见工具形态\n\n### 编辑器型：看得见、改得近\n\nVisual Studio Code + GitHub Copilot、Cursor 与 TRAE 把聊天、补全和多文件修改放在编辑器中。优点是文件、Diff 和诊断信息都在熟悉的界面里；缺点是产品通常与特定编辑器生态、账号体系或云服务绑定。\n\n适合：已经习惯图形化 IDE、需要频繁手工调整代码的人。\n\n### 终端型：组合自由、离工程最近\n\nOpenCode、Claude Code、Codex CLI 与 Kimi Code CLI 直接在项目终端工作。它们天然能够使用 Git、测试命令和脚本；其中 OpenCode 还能连接企业提供的 OpenAI-compatible 模型 API。\n\n适合：Linux 环境、模型需要替换、希望把工作流写成脚本或规则的团队。\n\n<Callout type=\"enterprise\" title=\"企业判断顺序\">\n  先确认数据能否出网、模型从哪里调用、凭证如何托管、命令是否需要审批；这些问题解决后，再比较界面和模型效果。\n</Callout>\n\n## 为什么本教程选择 OpenCode\n\n本教程的客户环境已经提供 OpenAI 兼容 API。OpenCode 的价值不在于“永远排名第一”，而在于它是开源终端 Agent，模型提供商可配置，适合 Linux 和企业模型网关。\n\n我们的主线因此是：\n\n> 企业模型 API → OpenCode → 本地项目 → Git 与测试 → GitHub Pages\n\n其他工具会被介绍，但不会在实践中来回切换。统一主线能让零基础读者把注意力留给任务方法，而不是反复适应界面。\n\n<Checklist\n  id=\"tools-map\"\n  items={[\n    \"我能说出本课约定的三家国外闭源模型和三家中国开放权重模型\",\n    \"我会同时检查模型能力、部署方式、数据边界和成本，而不是只看榜单\",\n    \"我能区分模型、Agent 与 Skill，并理解为什么实践主线选择 OpenCode\"\n  ]}\n/>\n"},{"path":"lessons/tools/02-opencode.mdx","raw":"---\ntitle: \"OpenCode：可替换模型的终端工作台\"\ndescription: \"理解 OpenCode 的工作循环、配置层级、权限与适用边界，为后面的企业 API 实践建立准确心智模型。\"\nsection: tools\norder: 4\nestimatedMinutes: 13\nprerequisites: [\"理解工具三层模型\"]\noutcomes:\n  - \"解释 OpenCode 如何读文件、调用命令和修改项目\"\n  - \"理解全局配置与项目配置的区别\"\n  - \"识别需要人工审批的高风险操作\"\ntags: [\"OpenCode\", \"终端 Agent\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"https://opencode.ai/docs/\", \"https://opencode.ai/docs/config/\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nOpenCode 是一个运行在终端中的开源 Coding Agent。它不是模型，也不会自己“思考”；它负责把你的指令、项目文件、工具结果和模型回复组织成一个可执行循环。\n\n## 一次任务里发生了什么\n\n当你输入“为首页增加移动端导航”时，OpenCode 通常会经历：\n\n1. 搜索项目结构和相关组件；\n2. 读取现有样式与约定；\n3. 向模型请求分析或计划；\n4. 修改一个或多个文件；\n5. 运行检查、测试或构建；\n6. 根据错误继续修正；\n7. 汇总改动和验证结果。\n\n真正决定质量的，不只有模型。项目里是否有清楚的 README、测试命令、类型定义和约束，也会改变结果。\n\n## 配置放在哪里\n\nOpenCode 支持多层配置。对本教程最重要的是：\n\n- 全局配置：`~/.config/opencode/opencode.json`，适合企业模型 Provider 和个人偏好；\n- 项目配置：项目根目录的 `opencode.json`，适合项目专属规则；\n- 项目说明：README、AGENTS.md 或通过 `instructions` 引用的文件。\n\nProvider 通常放在全局配置，避免每个项目重复；项目可提交的配置里不要包含密钥。\n\n## OpenCode 能做什么，也可能做错什么\n\n它可以搜索文件、生成 Diff、执行 Git 与测试命令。正因为它能动手，风险也从“回答错误”升级为“修改错误”：\n\n- 大范围覆盖用户已有修改；\n- 安装名字相似但恶意的依赖；\n- 把密钥写进配置或日志；\n- 运行破坏性命令；\n- 在测试不足时声称任务已完成。\n\n<Callout type=\"warning\" title=\"默认保持可回退\">\n  在干净的 Git 工作区开始任务；让 OpenCode 先展示计划；每个可验证阶段都提交一次；对删除、网络访问、系统级安装和凭证操作保持人工审批。\n</Callout>\n\n## 选择 OpenCode 的边界\n\n它特别适合模型必须走企业 API、开发发生在 Linux、工作需要脚本化的环境。以下场景可能不适合：\n\n- 读者完全无法使用终端；\n- 企业只允许某个已审计 IDE 插件；\n- 任务需要使用只有特定云 Agent 才提供的隔离环境；\n- 项目没有任何可运行的验证方式，且风险很高。\n\n工具不是安全边界的替代品。OpenCode 给你可观察的终端过程，但你仍要决定它能读什么、能执行什么、何时停下。\n\n<Checklist\n  id=\"tools-opencode\"\n  items={[\n    \"我知道 OpenCode 是 Agent 工具而不是模型\",\n    \"我能说出全局配置与项目配置各自适合放什么\",\n    \"我会在修改前确认 Git 工作区状态并保留回退点\"\n  ]}\n/>\n"},{"path":"lessons/tools/03-editor-agents.mdx","raw":"---\ntitle: \"编辑器型工具：在可见上下文里协作\"\ndescription: \"比较 Visual Studio Code + GitHub Copilot、Cursor 与 TRAE，理解三种编辑器型 AI Coding 路线及其中国使用边界。\"\nsection: tools\norder: 2\nestimatedMinutes: 16\nprerequisites: [\"理解模型、Agent、执行环境三层\"]\noutcomes:\n  - \"区分插件型 AI 助手与 AI 原生编辑器\"\n  - \"比较 GitHub Copilot、Cursor 与 TRAE 的工作方式\"\n  - \"按账号、网络、数据与团队治理要求选择工具\"\n  - \"避免把代码补全与自主 Agent 混为一谈\"\ntags: [\"Visual Studio Code\", \"GitHub Copilot\", \"Cursor\", \"TRAE\", \"IDE\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"GitHub Copilot 官方文档\", \"Cursor 官方文档\", \"TRAE 官方资料\", \"JetBrains 2025 中国开发者调研\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\n\n编辑器型工具把 AI 放在代码旁边。你选中的文本、当前文件、诊断错误和版本差异都能成为上下文，这让第一次使用的人更容易建立信任。\n\n这不是一张“谁最强”的排行榜。[JetBrains 2025 中国开发者调研](https://blog.jetbrains.com/zh-hans/research/2026/01/insights-into-china-s-developer-landscape-key-trends/)显示，GitHub Copilot 和 Cursor 在中国受访者中的使用率分别约为 26% 和 23%；调研同时提醒，问卷没有覆盖全部本土工具。TRAE 官方披露的是全球注册与活跃数据，也不能直接当成中国市场份额。本课因此选择三种**在中国开发者中具有代表性的产品路线**，不编造精确排名。\n\n## 同一个产品里可能有三种能力\n\n不要把它们混在一起：\n\n1. **补全**：根据光标附近内容预测下一段代码；\n2. **聊天或编辑**：根据指令解释代码、生成局部修改；\n3. **Agent 模式**：自主搜索多个文件、运行命令、循环修复。\n\n从第一种到第三种，工具的行动范围越来越大，所需审查也越来越严格。\n\n## 三款工具代表三种路线\n\n| 工具 | 产品形态 | 典型工作方式 | 更适合谁 | 先核对什么 |\n| --- | --- | --- | --- | --- |\n| **Visual Studio Code + GitHub Copilot** | 通用编辑器 + GitHub AI 服务 | 在熟悉的 VS Code 中使用补全、聊天、编辑、Agent、代码审查与工作区索引 | 已使用 VS Code、GitHub 和企业账号体系的团队 | Copilot 订阅、组织策略、可用模型、代码与聊天数据处理 |\n| **Cursor** | AI 原生代码编辑器 | 用 Ask 做只读探索，用 Agent 搜索代码库、编辑多文件、运行命令，再在 Diff 中审查 | 愿意更换编辑器、希望 AI 成为主要交互入口的个人与小团队 | 账号与订阅、模型服务可达性、代码库索引、后台 Agent 的网络和数据边界 |\n| **TRAE** | 面向中国与国际市场的 AI IDE | 在编辑器中结合补全、对话、Agent 与项目上下文，强调中文使用体验与开箱即用 | 重视国内网络体验、中文交互和较低上手门槛的学习者与团队 | 中国版/国际版差异、可用模型与额度、账号体系、企业部署和数据条款 |\n\n### Visual Studio Code + GitHub Copilot\n\nVisual Studio Code 本身是通用编辑器，**不是一个独立 AI Coding 产品**。课程里说的工具组合，是 VS Code 加上 GitHub Copilot 服务。\n\n[GitHub 官方功能矩阵](https://docs.github.com/en/copilot/reference/copilot-feature-matrix)显示，Copilot 在 VS Code 中已经不只是代码补全，还包括 Agent 模式、代码审查、工作区索引、MCP、自定义指令和 Agent Skills 等能力。它的优势是不用离开成熟的编辑器与 GitHub 工作流；限制是能力受 Copilot 订阅、组织策略、扩展版本和服务可用性共同影响。\n\n### Cursor\n\nCursor 把 AI 变成编辑器的核心入口。[Cursor 官方文档](https://docs.cursor.com/agent)把常见工作方式分为 Ask、Agent 等模式：Ask 适合只读理解，Agent 可以自主探索代码库、修改多个文件并运行命令。\n\n它适合希望减少手动选文件、把完整任务交给 Agent 的用户。但“自动找到上下文”仍然可能找错；启用自动运行命令或后台 Agent 时，还要单独检查网络、仓库授权和数据保留边界。\n\n### TRAE\n\nTRAE 是 AI 原生 IDE，提供中国版和国际版。它的代表性来自中文交互、国内产品与模型生态，以及较低的试用门槛。[TRAE 官方年度报告](https://forum.trae.cn/t/topic/239)披露其 2025 年全球注册用户超过 600 万、月活超过 160 万；这些是厂商自报的全球数据，只用于说明产品规模，不代表中国市场份额。\n\n个人使用前要确认当天可用模型、额度与版本；企业使用则要进一步核对 SaaS、VPC 或其他部署方式、代码索引范围和管理员控制，而不是因为产品来自国内就默认满足合规要求。\n\n## 编辑器的优势也是风险\n\n编辑器让很多证据保持可见：\n\n- 文件树、选区、诊断和 Diff 在同一个界面；\n- 适合“人主导、AI 高频辅助”的补全和局部编辑；\n- 前端、设计还原和代码审查可以利用截图与可视化上下文；\n- 初学者不必先记住大量终端命令。\n\n但 Agent 模式可以调用终端、改写多个文件，甚至连接 MCP 服务。界面更友好，不代表权限更小。\n\n## 它并不自动拥有完整上下文\n\n“AI 在编辑器里”不代表它看到了整个项目。被打开的文件、索引策略、忽略规则和上下文限制都会影响结果。一个常见错误是：用户以为工具知道某个接口，而它只看到了调用方。\n\n<Callout type=\"warning\" title=\"国内能打开，不等于企业可批准\">\n  下载成功、中文体验好、默认模型可用，只能证明个人可以开始试用。企业还必须确认数据传输位置、保留策略、账号管理、模型供应商、扩展更新与审计日志。\n</Callout>\n\n## 按场景做第一次选择\n\n| 你的起点 | 可以先试 | 理由 |\n| --- | --- | --- |\n| 团队已经统一使用 VS Code 与 GitHub | VS Code + GitHub Copilot | 改变最小，组织策略和仓库工作流集中 |\n| 个人开发，希望体验 AI-first 工作方式 | Cursor | Ask、Agent 与 Diff 审查形成完整编辑器循环 |\n| 中国网络环境、零基础或中文交互优先 | TRAE | 上手路径短，国内版产品与模型生态更近 |\n| 企业代码不能直接发送到未知云服务 | 先不选品牌 | 先完成数据分类、网络与部署审批，再做小规模试点 |\n\n无论选择哪一款，第一次试点都使用同一个低风险任务：只读解释一个公开或脱敏仓库，再做一次限定文件范围的小修改。不要用不同任务比较工具，否则你无法判断差异来自产品、模型还是任务本身。\n\n## 企业选型的五个问题\n\n- 代码和聊天内容发送到哪里？\n- 使用了哪些模型和第三方处理方？\n- 工作区索引是否包含敏感目录？\n- Agent 命令是否有审批与日志？\n- 账号、扩展和版本更新能否由管理员控制？\n\n如果这些问题没有答案，再顺滑的界面也不适合作为企业默认工具。\n\n<Callout type=\"note\" title=\"本教程为什么不三款都教\">\n  工具介绍负责建立选择能力；后面的实践只使用 OpenCode。固定一条主线，能让零基础读者把注意力放在任务拆解、验证和安全边界，而不是反复适应界面。\n</Callout>\n"},{"path":"lessons/tools/04-terminal-agents.mdx","raw":"---\ntitle: \"终端 Agent：把工程命令变成协作语言\"\ndescription: \"比较 OpenCode、Claude Code、Codex CLI 与 Kimi Code CLI，理解四种终端 Agent 路线及其中国使用边界。\"\nsection: tools\norder: 3\nestimatedMinutes: 18\nprerequisites: [\"理解模型、Agent、Skill 三层\"]\noutcomes:\n  - \"理解终端 Agent 的共享工作循环\"\n  - \"比较四款代表性终端 Agent 的产品边界\"\n  - \"按模型来源、网络、账号和权限选择工具\"\n  - \"用仓库验证命令约束任何终端 Agent\"\ntags: [\"CLI\", \"OpenCode\", \"Claude Code\", \"Codex CLI\", \"Kimi Code CLI\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"OpenCode 官方文档\", \"Claude Code 官方文档\", \"Codex CLI 官方文档\", \"Kimi Code 官方文档\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\n\nOpenCode、Claude Code、Codex CLI 和 Kimi Code CLI 的产品细节不同，但都围绕同一件事：让模型在终端里读取仓库、编辑文件、运行 Shell 命令，并根据结果继续行动。\n\n本课选择的是四种**在全球或中国开发者中具有代表性的产品路线**，不是使用率排名。终端 Agent 缺少口径一致的中国市场调查，因此不使用 GitHub Stars、厂商注册量或社交媒体热度拼出一张虚假的榜单。\n\n## 四款工具怎样不同\n\n| 工具 | 产品路线 | 主要优势 | 主要约束 | 更适合 |\n| --- | --- | --- | --- | --- |\n| **OpenCode** | 开源 Harness + 可配置 Provider | 支持多种模型 Provider，适合 OpenAI-compatible 企业网关；终端过程可观察 | 效果取决于所接模型、配置与权限，企业要自行维护组合 | 需要替换模型、连接企业 API、坚持开源工具链的 Linux 团队 |\n| **Claude Code** | Anthropic 的 Agentic Coding 产品 | 代码库理解、文件与命令工具、验证循环，以及 Skills、Hooks、MCP 等扩展体系 | 账号、支持地区、模型服务与企业数据条款必须先批准 | 已获准使用 Anthropic 服务，希望处理复杂跨文件任务的团队 |\n| **Codex CLI** | OpenAI 的本地终端 Coding Agent | 在本地仓库中检查、编辑和运行代码；可控制模型、推理强度、权限，并支持脚本与 CI | 需要可用的 OpenAI/ChatGPT 账号路径与组织策略；不是任意 Provider 前端 | 已使用 OpenAI 体系，需要交互式开发、审查与自动化的团队 |\n| **Kimi Code CLI** | Moonshot 的终端 Agent + Kimi Code 服务 | 面向中文开发者，支持读取和修改代码、运行命令、搜索文件，也可与 IDE 配合 | 需要核对会员权益、模型版本、额度、企业数据和服务条款 | 中国网络环境、中文交互和 Kimi 模型生态优先的个人或团队 |\n\n### OpenCode\n\n[OpenCode](https://opencode.ai/docs/)是开源终端 Agent。它最重要的特点不是绑定某个“最强模型”，而是把 Agent Harness 与模型 Provider 分开：团队可以连接不同厂商、本地模型或企业 OpenAI-compatible 网关。\n\n这也是本教程选择它作为实践主线的原因。课程环境已经提供企业兼容 API，读者可以在不更换任务方法的前提下替换模型。不过，可配置不等于自动安全；Provider、日志、网络和权限仍由团队负责。\n\n### Claude Code\n\n[Claude Code 官方文档](https://code.claude.com/docs/en/overview)把它定义为可以读取代码库、编辑文件、运行命令并集成开发工具的 Agentic Coding 工具。终端是其完整能力入口，同时还覆盖 IDE、桌面和 Web 等形态。\n\n它适合长链路、跨文件的软件工程任务，但不能只比较模型效果。还要检查 Anthropic 支持地区、登录和计费方式、组织管理、代码数据处理，以及命令权限是否符合企业要求。\n\n### Codex CLI\n\n[Codex CLI 官方文档](https://developers.openai.com/codex/cli/)将其定位为在终端中检查、编辑和运行代码的本地 Agent。用户可以选择模型、推理强度、权限与命令，也能通过 `codex exec` 接入脚本和 CI。\n\n课程统一使用正式名称 **Codex CLI**，不写成 “CodeX”。它适合已经批准 OpenAI 或 ChatGPT 工作区的团队；如果企业只提供一个通用 OpenAI-compatible Base URL，不能先假定它与 Codex CLI 的账号、模型和功能完全兼容。\n\n### Kimi Code CLI\n\n[Kimi Code 官方文档](https://www.kimi.com/code/docs/)说明，Kimi Code 通过 CLI 和 VS Code 扩展提供代码阅读、文件编辑与命令执行能力。CLI 会在终端中根据工具反馈规划下一步，属于完整 Agent，而不只是问答命令。\n\n它为中国开发者提供了更直接的中文产品与账号路径，但“国内服务”同样需要审计：个人会员权益不等于企业授权，模型版本、额度、数据用途和组织控制都要逐项确认。\n\n后续工具章节会把通用能力单独展开：先学习 [Agent 与 Subagent](/vibe_coding_guide/tools/agent-subagents/) 的任务编排和上下文隔离，再学习 [MCP](/vibe_coding_guide/tools/mcp/) 的工具连接边界，最后学习 [Skill](/vibe_coding_guide/tools/agent-skills/) 如何沉淀可复用方法。它们不再混在本页的产品比较中。\n\n## 真正可迁移的能力\n\n不要只学某个斜杠命令。更值得练习的是：\n\n- 在任务开始前检查 `git status`；\n- 给出目标、范围和验收标准；\n- 要求先读相关文件再计划；\n- 控制一次修改的大小；\n- 指定必须运行的测试或构建；\n- 审查 Diff，并在异常时回退。\n\n这些能力换一个 CLI 仍然成立。\n\n## 为什么模型相同，结果仍会不同\n\nAgent Harness 会决定：\n\n- 系统提示如何描述工具；\n- 哪些文件被自动加入上下文；\n- 命令如何审批和沙箱化；\n- 长对话如何压缩；\n- Diff 如何生成、应用和回退；\n- 失败后是否自动重试。\n\n因此“模型 A 在工具 X 里很好用”不能直接推出它在工具 Y 里表现相同。\n\n## 中国环境先过四道门\n\n| 门槛 | 必须确认 |\n| --- | --- |\n| 网络 | 官网、登录、模型 API、更新源和依赖下载是否稳定且被企业允许 |\n| 账号 | 使用个人订阅、企业工作区、API Key，还是内部统一身份 |\n| 数据 | 代码、Prompt、索引、命令输出和遥测发送到哪里、保留多久 |\n| 权限 | 能否限制读取范围、命令、网络、MCP、提交、推送与部署 |\n\n能正常安装只代表二进制可以运行，不代表模型服务可达，更不代表企业已经批准。反过来，国内账号和中文界面也不能自动替代数据分类、合同与审计。\n\n## 按场景选择第一款\n\n| 场景 | 优先评估 |\n| --- | --- |\n| 企业已有 OpenAI-compatible 模型网关，需要自由换模型 | OpenCode |\n| Anthropic 服务、账号与数据条款已经批准 | Claude Code |\n| OpenAI / ChatGPT 工作区已经批准，并需要终端与自动化 | Codex CLI |\n| 中国网络与中文交互优先，团队已批准 Kimi Code | Kimi Code CLI |\n| 以上服务都未获企业批准 | 暂不安装，先完成 Provider 与数据边界确认 |\n\n这不是永久选型。用同一仓库、同一模型层级、同一任务和同一验收标准做试点，记录任务完成率、人工纠正次数、命令风险与总成本，再决定是否扩大使用。\n\n## 终端的优势也是风险\n\n终端拥有项目最真实的反馈：命令成功或失败、测试通过或失败、文件是否存在。但终端也能访问凭证、网络和系统资源。\n\n<Callout type=\"warning\" title=\"把命令输出当作证据，不把命令权限当作默认\">\n  允许 Agent 运行项目内的只读检查和测试，与允许它修改系统、访问任意网络或删除目录，是完全不同的授权等级。\n</Callout>\n\n## 一个品牌无关的任务模板\n\n```text\n目标：修复移动端导航遮挡正文的问题。\n范围：只修改导航组件和相关样式；不要升级依赖。\n先做：读取组件、全局样式和现有浏览器测试，给出 3–5 步计划。\n验收：\n1. 375px 与 1280px 视口均可导航；\n2. 键盘可打开菜单并访问全部链接；\n3. npm test 通过；\n4. 汇总实际修改和仍存在的风险。\n```\n\n当工具换掉时，这种任务描述仍然有效。\n\n<Callout type=\"note\" title=\"介绍四款，实践只走一条线\">\n  后续实践统一使用 OpenCode，不要求同时安装 Claude Code、Codex CLI 和 Kimi Code CLI。这里的目标是会选、会审计、会迁移方法，而不是收集工具。\n</Callout>\n"},{"path":"lessons/tools/05-agent-subagents.mdx","raw":"---\ntitle: \"Agent 与 Subagent：主线、分工与上下文隔离\"\ndescription: \"理解 Agent 的工作循环、主 Agent 与 Subagent 的职责，以及何时值得委派、并行和限制工具权限。\"\nsection: tools\norder: 5\nestimatedMinutes: 15\nprerequisites: [\"了解终端型 Coding Agent\", \"理解模型与 Agent 的区别\"]\noutcomes:\n  - \"解释 Agent 如何围绕工具反馈循环工作\"\n  - \"区分主 Agent、Plan Agent 与 Subagent\"\n  - \"判断任务是否适合委派或并行\"\n  - \"为 Subagent 写清输入、权限与交付格式\"\ntags: [\"Agent\", \"Subagent\", \"委派\", \"上下文隔离\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"OpenCode Agents 官方文档\", \"Claude Code Subagents 官方文档\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n模型负责理解与生成，**Agent** 则把模型放进一个可以观察环境、调用工具、检查结果并继续行动的工作循环。终端里看到的读文件、搜索代码、修改文件、运行测试和重试，都属于 Agent Harness 组织出来的行为。\n\n```text\n接收目标\n  ↓\n读取上下文 → 选择工具 → 执行动作 → 观察结果\n     ↑                              ↓\n     └────── 调整计划并继续 ─────────┘\n  ↓\n用测试、Diff 与验收标准结束任务\n```\n\n## 主 Agent 负责保持任务主线\n\n主 Agent 直接与你协作，持有当前会话、目标、约束和已经作出的决定。它应该：\n\n- 澄清目标、范围和完成定义；\n- 决定先探索、计划还是修改；\n- 把必要工作委派给 Subagent；\n- 汇总多个结果并处理冲突；\n- 对最终修改、验证和风险报告负责。\n\nOpenCode 把可直接切换的 **Build** 与 **Plan** 称为 Primary Agents。Build 可以在权限范围内修改与执行；Plan 适合只读探索和方案分析。Claude Code 也提供 Plan 等工作模式，但入口与权限配置并不完全相同。\n\n## Subagent 是独立上下文中的执行者\n\n**Subagent** 接收一项被明确划分的任务，在独立上下文中读取文件、调用获准工具并返回结果。它的价值首先是**上下文隔离和专业分工**，其次才是并行。\n\n| 方面 | 主 Agent | Subagent |\n| --- | --- | --- |\n| 上下文 | 保留整个任务的对话与决策 | 通常从一份委派说明开始 |\n| 职责 | 维护主线、整合结果、决定下一步 | 完成边界清晰的专项任务 |\n| 输出 | 最终修改、验证证据与风险 | 结论、证据、建议或限定范围的改动 |\n| 权限 | 按当前会话和项目策略配置 | 可以进一步限制工具、目录与命令 |\n| 适合 | 强依赖连续决策的工作 | 调研、搜索、审查和相互独立的子任务 |\n\nSubagent 不会自动继承主会话中所有隐含信息。主 Agent 已经读过哪些文件、你口头否定过什么方案、哪些边界只能人工决定，都需要在委派说明中明确传递。\n\n## 什么任务值得委派\n\n适合委派的任务通常同时具备三个条件：\n\n1. **边界清晰**：能说清要检查的目录、问题或候选方案；\n2. **结果可汇总**：输出可以是事实、表格、风险列表或独立补丁；\n3. **低耦合**：不会与其他执行者同时修改同一批核心文件。\n\n| 任务 | 是否适合 Subagent | 原因 |\n| --- | --- | --- |\n| 搜索仓库中所有认证入口并列出文件与行号 | 适合 | 只读、范围清楚、结果容易核查 |\n| 独立检查移动端、无障碍和控制台错误 | 适合 | 可以分成互不覆盖的验证维度 |\n| 决定产品需求优先级 | 通常不适合 | 需要业务判断与持续对话 |\n| 三个 Agent 同时重构同一个组件 | 不适合 | 修改冲突与整合成本很高 |\n| “帮我把整个项目做好” | 不适合 | 没有边界、交付格式和停止条件 |\n\n<Callout type=\"warning\" title=\"多 Agent 不等于自动更快\">\n  每次委派都要付出上下文重建、结果核验和冲突整合成本。任务强依赖前序决策，或只需读取两三个文件时，主 Agent 直接完成通常更简单。\n</Callout>\n\n## 一份可执行的委派说明\n\n```text\n角色：只读代码审查 Subagent。\n目标：检查 src/components/ 中的移动端导航实现。\n范围：只读相关组件、样式和测试；不要修改文件。\n重点：键盘操作、焦点管理、375px 溢出和控制台错误。\n证据：每个问题给出文件路径、具体位置和复现条件。\n交付：按严重程度排序；没有问题也要说明检查过什么。\n停止：不要启动部署、提交或外部消息。\n```\n\n这段说明包含角色、目标、范围、证据、交付格式和停止条件。模型名称不是最重要的字段；如果边界含糊，换更强模型也可能产生难以整合的结果。\n\n## OpenCode 与 Claude Code 的共同点和差异\n\n两者都支持专门 Agent、独立上下文、工具限制与任务委派，但产品入口不同：\n\n- OpenCode 区分 Primary Agent 与 Subagent，可用 `Tab` 切换主 Agent，通过 `@` 提及专门 Agent，也可让主 Agent调用子任务；\n- Claude Code 的 Subagent 由主会话委派，能够配置自己的提示、工具、权限与预加载 Skill；\n- 两边的默认 Agent、可否嵌套委派、并行方式和上下文继承规则都可能变化，不能把一个产品的配置文件直接复制给另一个。\n\n使用前以 [OpenCode Agents](https://opencode.ai/docs/agents/)与 [Claude Code Subagents](https://code.claude.com/docs/en/sub-agents)官方文档为准。\n\n<Checklist\n  id=\"tools-agent-subagents\"\n  items={[\n    \"我能区分主 Agent、Plan Agent 与 Subagent\",\n    \"我只把边界清晰、结果可汇总的任务交给 Subagent\",\n    \"委派说明包含范围、权限、证据、交付格式和停止条件\",\n    \"我会由主 Agent 或人工复核 Subagent 的结论\"\n  ]}\n/>\n"},{"path":"lessons/tools/06-mcp.mdx","raw":"---\ntitle: \"MCP：把外部工具与数据接入 Agent\"\ndescription: \"理解 MCP server、Tools、Resources 与连接边界，学会按最小权限审计本地和远程 MCP。\"\nsection: tools\norder: 6\nestimatedMinutes: 13\nprerequisites: [\"理解 Agent 与 Subagent\", \"知道 Agent 会调用工具\"]\noutcomes:\n  - \"解释 MCP 在 Agent 工具链中的位置\"\n  - \"判断一个需求是否适合通过 MCP 接入\"\n  - \"理解本地和远程 MCP 的信任边界\"\n  - \"按来源、凭据、数据和权限审计 MCP\"\ntags: [\"MCP\", \"Model Context Protocol\", \"Tools\", \"企业安全\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"OpenCode MCP 官方文档\", \"Claude Code MCP 官方文档\", \"Model Context Protocol 官方规范\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nAgent 默认只能使用产品内置的读文件、搜索、编辑和 Shell 等工具。**MCP（Model Context Protocol）**提供一套连接方式，让 Agent 能发现并使用外部系统提供的能力，例如查询 GitHub、读取内部文档、访问数据库或控制浏览器。\n\n```text\n用户目标\n  ↓\nAgent / Subagent\n  ├─ 内置工具：Read、Edit、Shell、Search\n  └─ MCP Client\n       ↓\n     MCP Server\n       ├─ 外部 Tools\n       ├─ Resources\n       └─ Prompts\n            ↓\n        GitHub / 数据库 / 文档 / 浏览器\n```\n\nMCP 解决“怎样让不同 Agent 连接外部能力”的接口问题，不替你决定业务流程，也不自动保证服务可信。\n\n## MCP server 可以提供什么\n\n| 能力 | 含义 | 例子 |\n| --- | --- | --- |\n| Tools | Agent 可以主动调用的操作 | 搜索 Issue、查询数据库、创建工单 |\n| Resources | 可以读取的结构化或文件型上下文 | 文档、Schema、仓库元数据 |\n| Prompts | Server 提供的可复用提示入口 | 诊断流程、查询模板 |\n\n具体 Agent 产品不一定以相同方式展示全部能力。OpenCode 文档重点呈现 MCP Tools；Claude Code 还提供 MCP 资源引用和连接管理。课程只要求理解协议角色，实际可用功能应以当前客户端与 Server 文档为准。\n\n## 本地与远程 MCP 是两种信任边界\n\n| 类型 | 运行位置 | 主要风险 |\n| --- | --- | --- |\n| 本地 MCP | 由本机命令启动 | 安装包与脚本供应链、本地文件和环境变量访问 |\n| 远程 MCP | 通过网络连接服务 | 账号授权、数据出境、服务端日志、可用性与撤销 |\n\n“本地运行”不等于低风险：恶意或维护失控的包仍可能读取凭据、文件和网络。“远程服务”也不等于不能使用，但必须明确由谁运营、发送哪些数据、凭据放在哪里以及如何撤销。\n\n## 连接前做五项审计\n\n1. **来源**：Server 来自官方、内部受控仓库还是未知包？谁维护版本？\n2. **能力**：它暴露哪些 Tools 和 Resources？是否包含写入、删除、发送或部署？\n3. **凭据**：API Key、OAuth Token 和数据库密码存在哪里？会不会进入仓库或 Prompt？\n4. **数据**：代码、查询、工具参数和返回值会发送到哪里、保留多久？\n5. **权限**：能否按 Server、Tool、Agent 和项目设置 allow、ask、deny？\n\n<Callout type=\"warning\" title=\"工具描述也会消耗上下文\">\n  MCP Server 暴露的工具越多，Agent 越难选择，工具说明也可能占用更多上下文。先只启用当前任务需要的 Server 和 Tool，不要把“能连接”变成“全部默认开启”。\n</Callout>\n\n## 第一次试点应该很小\n\n推荐从只读场景开始：\n\n```text\n目标：使用文档 MCP 查找框架的路由规范。\n允许：搜索并读取公开文档。\n禁止：写文件、发送消息、修改远程资源或上传仓库内容。\n交付：列出使用的 MCP Tool、查询词、来源链接和仍不确定的地方。\n```\n\n观察 Agent 实际调用了哪个 Tool、传出了什么参数、返回了什么，再决定是否扩大权限。不要把生产数据库写权限或企业消息发送能力作为第一个 MCP 练习。\n\n## OpenCode 与 Claude Code 中的 MCP\n\n- OpenCode 在配置的 `mcp` 字段中管理本地或远程 Server，并允许按全局或 Agent 权限控制 MCP Tools；\n- Claude Code 支持项目、用户等连接作用域，并可通过 `/mcp` 管理连接与 OAuth；\n- 两者的配置文件、认证方式、命令入口和工具命名不同，但安全问题相同：来源、凭据、数据、权限与审计。\n\n安装与连接前核对 [OpenCode MCP](https://opencode.ai/docs/mcp-servers/)、[Claude Code MCP](https://code.claude.com/docs/en/mcp)和 [Model Context Protocol](https://modelcontextprotocol.io/docs/)官方文档。\n\n<Checklist\n  id=\"tools-mcp\"\n  items={[\n    \"我能判断一个需求是否需要连接外部工具或数据\",\n    \"我知道本地 MCP 和远程 MCP 的主要信任边界\",\n    \"我不会把凭据写进仓库、Prompt 或 MCP 配置示例\",\n    \"我会从只读、最小 Tool 集开始验证新的 MCP Server\"\n  ]}\n/>\n"},{"path":"lessons/tools/07-agent-skills.mdx","raw":"---\ntitle: \"Skill：把一次有效协作变成能力\"\ndescription: \"理解 SKILL.md、渐进加载与作用域：Skill 不是一段更长的 Prompt，而是一套可复用、可审计的工作方法。\"\nsection: tools\norder: 7\nestimatedMinutes: 12\nprerequisites: [\"理解 Agent 与 Subagent\", \"理解 MCP 的工具连接边界\"]\noutcomes:\n  - \"判断一段经验是否值得封装成 Skill\"\n  - \"理解 OpenCode 如何发现并按需加载 SKILL.md\"\n  - \"为团队 Skill 选择项目级或个人级作用域\"\ntags: [\"Agent Skills\", \"SKILL.md\", \"OpenCode\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"Agent Skills 开放规范\", \"OpenCode Agent Skills 官方文档\", \"GitHub Agent Skills 官方文档\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n一个好 Prompt 的价值通常只活在一次对话里。Skill 的价值是把其中**稳定、可复查、可复用**的部分装进一个小目录：下一次由任何合适的 Agent 发现它、读取它，并按同一套边界做事。\n\n按 [Agent Skills 开放规范](https://github.com/agentskills/agentskills)，Skill 的根目录至少有一个 `SKILL.md`；也可以带上脚本、参考资料和模板。Agent 先只读取 `name` 与 `description`，任务匹配时才读取正文，真正需要时再使用目录里的资源。这叫“渐进加载”。\n\n```text\ngithub-pages-release-check/\n├── SKILL.md          # 必需：什么时候用、怎么做、何时停止\n├── scripts/          # 可选：需要确定性的重复操作\n├── references/       # 可选：按需读取的长文档、规范、错误对照\n└── assets/           # 可选：模板、图标、样例文件\n```\n\n## 什么内容值得做成 Skill\n\n<Callout type=\"tip\" title=\"先别把所有知识都塞进 Skill\">\n  每次都相关的短规则，放仓库指令；一次性的回答，留在对话；固定且不需要判断的操作，优先写成脚本。只有“会反复出现、包含判断与验证步骤”的任务，才值得做成 Skill。\n</Callout>\n\n适合封装的例子包括发布前检查、代码审查、故障诊断和固定格式的研究报告。一个 Skill 可以调用脚本，也可以使用 Agent 已有的工具，但它的核心仍是可复用的工作方法。\n\n## OpenCode 会在哪里找？\n\n本教程的主线工具 OpenCode 已原生支持 Agent Skills。项目内推荐放在：\n\n```bash\nmkdir -p .opencode/skills/github-pages-release-check\n```\n\n然后创建：\n\n```text\n.opencode/skills/github-pages-release-check/SKILL.md\n```\n\nOpenCode 也会识别项目内的 `.claude/skills/`、`.agents/skills/`，以及用户目录中的对应位置；它把可用 Skill 的名称和描述展示给 Agent，在需要时通过 `skill` 工具加载全文。路径、字段和权限会随工具版本演进，安装前以 [OpenCode Agent Skills 文档](https://opencode.ai/docs/skills/) 为准。\n\n## 作用域：先小后大\n\n| 作用域 | 位置 | 适合 | 风险 |\n| --- | --- | --- | --- |\n| 项目级 | `.opencode/skills/` | 发布检查、仓库测试、领域术语 | 会跟随仓库共享，应审查后提交 |\n| 个人级 | `~/.config/opencode/skills/` | 你的写作偏好、个人环境诊断 | 容易在不同项目误触发 |\n| 团队分发 | 受控模板仓库或内部目录 | 公司规范、合规流程 | 需要版本、审核与撤销机制 |\n\n对刚开始的团队，优先做**项目级、只读、低权限**的 Skill。把“能删除、能发消息、能部署”的动作留在明确审批之后；不要因为 Skill 是 Markdown，就忽略它可能引导 Agent 读取文件、运行命令或调用外部服务。\n\n## 一个触发描述，决定它会不会被正确使用\n\n坏描述：`帮助处理网站。`\n\n好描述：`在请求发布静态站点到 GitHub Pages 前，检查构建、仓库子路径、站内链接和无障碍证据；不执行部署、不修改文件。`\n\n前者太宽，会在不相关任务中出现；后者说清了**时机、目标、边界**。这正是 Skill 最重要的接口。\n\n<Checklist\n  id=\"tools-agent-skills\"\n  items={[\n    \"我只把反复出现且包含判断与验证的流程做成 Skill\",\n    \"我知道项目级 Skill 应放在 .opencode/skills/<名称>/SKILL.md\",\n    \"我会先用只读、低风险任务验证一个新 Skill\",\n    \"我不会把 API Key、客户数据或高权限默认授权写进 Skill\"\n  ]}\n/>\n"},{"path":"lessons/tools/08-skill-map.mdx","raw":"---\ntitle: \"常用 Skill 图谱：先审计，再安装\"\ndescription: \"用高复用任务而非下载榜选择 Skill，并建立来源、权限、脚本与验证四步审计法。\"\nsection: tools\norder: 8\nestimatedMinutes: 13\nprerequisites: [\"理解 Skill 的作用域与渐进加载\", \"了解终端型 Coding Agent\"]\noutcomes:\n  - \"按任务类别识别高复用的 Skill\"\n  - \"在安装前审计 SKILL.md、脚本、依赖与网络权限\"\n  - \"为团队建立可撤销的 Skill 引入记录\"\ntags: [\"Skill 图谱\", \"供应链安全\", \"审计\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"GitHub Agent Skills 官方文档\", \"OpenCode Agent Skills 官方文档\", \"OpenAI Skills 仓库\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n“流行”不是安全、适配或高质量的同义词。Skill 市场变化很快，一份下载排行榜也会很快过期；更可靠的起点是找那些跨项目反复出现、输入和验收都清楚的任务类型。\n\n下面是当前最值得零基础团队认识的高复用图谱。名称是常见能力标签，不承诺每个 Agent 都用同一个安装命令或目录。\n\n| 能力类别 | 常见 Skill | 用它解决什么 | 最小验收 |\n| --- | --- | --- | --- |\n| 文档 | `documents`、`docx` | 生成、修改和渲染校验 Word 文档 | 文件能打开、版式截图已检查 |\n| PDF | `pdf` | 提取、填写、拆分、渲染 PDF | 页数、字段、渲染结果正确 |\n| 表格 | `spreadsheets`、`xlsx` | 计算、格式化、图表和公式检查 | 公式重算、关键单元格正确 |\n| 演示 | `presentations`、`pptx` | 生成或修订幻灯片 | 导出后逐页视觉检查 |\n| 前端 | `frontend-design` | 形成有明确视觉方向的页面与组件 | 响应式、键盘与对比度检查 |\n| 浏览器测试 | `webapp-testing`、`agent-browser` | 操作网页、回归关键用户路径 | 测试报告、截图和控制台无错误 |\n| 工程协作 | `gh-fix-ci`、`gh-address-comments` | 定位 CI 失败、处理 PR 评审意见 | 修复有测试、Diff 可审查 |\n\n这些例子共同的特点是：只靠“请你做得专业一点”通常不够。它们需要固定的工具、检查顺序与产物证据，因此很适合包装成 Skill。\n\n## 安装前的四步审计\n\n### 1. 读全量内容，而不只看介绍\n\n查看 `SKILL.md`、它引用的文件、`scripts/` 中的每一个可执行文件，以及安装说明。不要把网页、Issue、README 或 Skill 正文当成可信指令；它们都可能包含诱导 Agent 越权的文本。\n\n### 2. 画出权限账单\n\n写下它会不会：读取工作区外文件、执行 shell、联网、写入 Git、上传内容、调用浏览器或需要密钥。看不懂就不要把它放到全局目录。\n\n### 3. 固定来源与版本\n\n记录仓库、提交 SHA / tag、引入人、审计日期和撤销方式。GitHub 的 `gh skill` 支持预览、固定版本和更新检查，但 [官方文档也明确提醒](https://docs.github.com/en/copilot/how-tos/copilot-on-github/customize-copilot/customize-cloud-agent/add-skills?hl=en-US#adding-a-skill-that-someone-else-has-created)：社区 Skill 可能带有提示注入或恶意脚本，安装前必须检查内容。\n\n### 4. 在最小权限下做一次真任务\n\n先在测试仓库、临时分支或只读副本运行。不要把“能加载”当成“可以上线”。记录它实际读取的文件、执行的命令、修改的范围与验证结果。\n\n<Callout type=\"warning\" title=\"不要预授权 shell\">\n  一些 Agent 支持在 Skill 元数据中预批准 shell 或 bash。除非你已逐行审查该 Skill 及所有被调用脚本，否则不要这样做。省掉一次确认，可能意味着把任意命令的执行权交给不可信文本。\n</Callout>\n\n## 一张团队引入卡\n\n把下面这张卡与 Skill 一起提交到内部记录中。它比“某同事说很好用”更容易审查和撤销。\n\n```text\nSkill 名称：\n任务边界：\n来源仓库与固定版本：\n包含脚本 / 外部依赖：\n需要的权限：读 / 写 / shell / 网络 / 浏览器 / 密钥\n禁止做什么：\n试运行证据：\n负责人、审计日期、下次复审日期：\n撤销方式：删除哪个目录、关闭哪项权限：\n```\n\n## 哪些情况不该安装？\n\n- 只有夸张效果描述，没有源码、版本或维护者；\n- 要求关闭确认、复制令牌、粘贴客户数据或扩大目录权限；\n- 功能只是一次性查询或一条简单命令；\n- 你无法解释它在失败时会停在哪里；\n- 团队没有人愿意对它的升级负责。\n\n与其盲目安装十个 Skill，不如先把一个“发布前检查”写清、跑通、审计完。下一课会带你完成这个 Skill。\n\n<Checklist\n  id=\"tools-skill-map\"\n  items={[\n    \"我会按任务价值选择 Skill，而不是追逐下载榜\",\n    \"我会审计 SKILL.md、引用资源、脚本和网络行为\",\n    \"我会为第三方 Skill 固定来源、版本和负责人\",\n    \"我知道 Skill 的成功标准必须包含可观察的验证证据\"\n  ]}\n/>\n"},{"path":"lessons/methods/01-prompt-engineering.mdx","raw":"---\ntitle: \"Prompt Engineering：把单次任务说清楚\"\ndescription: \"用目标、范围、约束、验收和输出格式写出一次可执行的 Agent 任务描述。\"\nsection: methods\norder: 1\nestimatedMinutes: 10\nprerequisites: [\"至少完成一次完整实践\"]\noutcomes:\n  - \"把模糊愿望改写成可执行任务\"\n  - \"区分 Prompt、Context、Harness 和 Loop 的职责\"\n  - \"为一次 Agent 调用写出可观察的完成标准\"\ntags: [\"Prompt Engineering\", \"任务描述\", \"验收标准\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Anthropic Prompt Engineering 官方文档\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nPrompt Engineering 处理的是**一次任务描述**：你希望 Agent 这一次完成什么、不能做什么，以及怎样判断它完成了。它不是把整个仓库塞进提示词，也不是设计长期自动化系统。\n\n## 可借鉴的 Prompt Skill\n\n[grill-me](https://github.com/chenmingmin/grill-me) 适合在执行前连续追问需求，暴露歧义、遗漏和隐藏约束；[Superpowers 的 brainstorming Skill](https://github.com/obra/superpowers) 则把澄清问题、比较方案和确认设计组织成可复用流程。它们解决的是“把想法说清楚”，不是替代后续的规格、测试或人工审批。\n\n## 一条够用的任务指令\n\n```text\n目标：修复 GitHub Pages 子路径下的搜索结果跳转。\n范围：只检查搜索页面、路由辅助函数和现有 E2E 测试。\n约束：不更换 Pagefind，不改课程内容，不读取密钥。\n背景：本地根路径正常，生产 base 是 /vibe_coding_guide/。\n验收：点击搜索结果进入正确深层 URL；npm test 通过。\n输出：先报告计划，完成后报告实际命令、结果和未执行的检查。\n```\n\n## Prompt 的六个字段\n\n| 字段 | 要回答的问题 | 常见错误 |\n| --- | --- | --- |\n| 目标 | 哪个用户结果要改变？ | 只说“优化一下” |\n| 范围 | 哪些文件或行为在内？ | 默认整个仓库都能改 |\n| 约束 | 哪些东西不能碰？ | 把偏好写成硬性要求 |\n| 背景 | 哪些事实影响判断？ | 粘贴无用途的全部日志 |\n| 验收 | 什么结果可观察或运行验证？ | 用“写得好”代替标准 |\n| 输出 | 先分析、计划还是修改？ | 不要求报告实际证据 |\n\n如果需求涉及多个模块、依赖、权限或发布，先让 Agent 只读分析和计划；低风险的明确修改也必须验证。\n\n## Prompt 与其他方法的边界\n\n| 方法 | 解决什么问题 |\n| --- | --- |\n| Prompt Engineering | 这一次怎么把任务说清楚 |\n| Context Engineering | Agent 这一次应该看到哪些信息 |\n| Spec-Driven Development | 多步实现的规格和长期依据是什么 |\n| Harness Engineering | Agent 能使用哪些工具、权限和反馈 |\n| Loop Engineering | 任务如何重复执行、验证和停止 |\n\n不要用更长的 Prompt 代替后面四类工程工作。\n\n<Checklist id=\"methods-prompt\" items={[\n  \"任务描述包含目标、范围、约束、背景和验收\",\n  \"我能把形容词改成用户可观察的结果\",\n  \"我会要求 Agent 报告实际运行的命令与证据\",\n  \"我知道 Prompt 不负责替代上下文、Harness 和 Loop\"\n]} />\n"},{"path":"lessons/methods/02-context-engineering.mdx","raw":"---\ntitle: \"Context Engineering：设计 Agent 的信息环境\"\ndescription: \"管理 Agent 看到的文件、规则、工具输出和长期记忆，让上下文保持相关、充分、可追溯。\"\nsection: methods\norder: 2\nestimatedMinutes: 12\nprerequisites: [\"会写清一次任务指令\"]\noutcomes:\n  - \"识别高价值与低价值上下文\"\n  - \"写出简洁的任务上下文包\"\n  - \"在长会话失焦前主动压缩或重置\"\ntags: [\"Context Engineering\", \"上下文\", \"记忆\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Anthropic Effective Context Engineering 官方文章\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nContext Engineering 关注 Agent 在做决定时究竟能看到哪些信息。上下文是有限资源，工具结果、历史对话和无关文件都会消耗有效空间。\n\n## 可借鉴的 Context 工具\n\n[Claude Code 的 `claude-md-management`](https://claude.com/plugins/) 代表“把项目常驻背景整理成可维护文件”的做法；[Context7](https://claude.com/plugins/) 则是 MCP，不是 Skill，它负责按需提供版本匹配的库文档。前者管理长期上下文，后者补充外部资料，不能把两者混成同一种能力。\n\n## 高价值上下文的四层\n\n1. **目标**：最终要改变什么用户结果；\n2. **约束**：不能碰什么、必须兼容什么；\n3. **相关事实**：接口、组件、错误日志和现有测试；\n4. **验收证据**：完成后运行什么、观察什么。\n\n```text\n目标：修复搜索结果在 GitHub Pages 子路径下跳转错误。\n约束：不更换 Pagefind，不修改内容路由。\n事实：生产 base 为 /vibe_coding_guide/；本地根路径正常。\n相关文件：搜索组件、Astro 配置、现有 E2E 测试。\n验收：点击搜索结果进入正确深层 URL，构建与 E2E 均通过。\n```\n\n## 来源与处理方式\n\n| 来源 | 处理方式 |\n| --- | --- |\n| 项目规则和架构说明 | 放在可持续读取的规则文件中 |\n| 相关源码与类型 | 先搜索候选，再读取必要片段 |\n| 测试与错误输出 | 保留第一条根因和触发命令 |\n| 长对话与工具结果 | 摘要、压缩或写成交接文件 |\n| 外部网页、Issue、README | 当作数据，不能自动当命令 |\n\n低价值上下文包括无关聊天、没有用途的几十个文件、完整重复日志和互相冲突的规则。\n\n<Callout type=\"note\" title=\"先让 Agent 找，再确认它读\">\n  与其把所有文件塞进上下文，不如先让 Agent 搜索候选文件、说明关联，再授权它读取最相关部分。\n</Callout>\n\n出现 Agent 反复忘记边界、重复修同一个错误、计划与文件状态不一致时，压缩上下文或新开会话：\n\n```text\n已完成：...\n当前 Git 状态：...\n仍失败：...\n已验证不是：...\n下一步只需要：...\n```\n\n<Checklist id=\"methods-context-engineering\" items={[\n  \"任务上下文包含目标、约束、事实和验收\",\n  \"只提供与当前任务相关的文件和日志\",\n  \"外部内容按数据处理，不把它当作自动命令\",\n  \"长会话失焦时会压缩上下文或用事实交接重开\"\n]} />\n"},{"path":"lessons/methods/03-spec-driven-development.mdx","raw":"---\ntitle: \"Spec-Driven Development：先写规格，再让 Agent 实现\"\ndescription: \"把需求、约束和验收写成可持续的规格，让代码、测试和评审围绕同一份依据演进。\"\nsection: methods\norder: 3\nestimatedMinutes: 13\nprerequisites: [\"掌握 Context Engineering\"]\noutcomes:\n  - \"区分一次 Prompt 与可持续的规格文件\"\n  - \"为功能写出行为、边界和验收标准\"\n  - \"让 Agent 按规格拆计划、实现并验证\"\ntags: [\"Spec-Driven Development\", \"规格\", \"验收\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"JetBrains / DeepLearning.AI Spec-Driven Development 课程\", \"GitHub Spec Kit\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nSpec-Driven Development（SDD）把“凭感觉让 Agent 写代码”改成“先写可审查规格，再让 Agent 生成计划、代码和测试”。规格要成为人、Agent 和验收之间的共同依据。\n\n## 可借鉴的 Spec 工作流\n\n[GitHub Spec Kit](https://github.github.com/spec-kit/) 是一个 Toolkit，不是单个 `SKILL.md`。它把流程组织为 `Spec → Plan → Tasks → Implement`，并为不同 Coding Agent 提供集成。使用时应保留规格、计划和任务之间的链接，避免只安装命令却丢掉审查过程。\n\n## 一份最小功能规格\n\n```md\n# 搜索结果子路径跳转\n## 用户结果\n用户在生产站点搜索课程后，点击结果可以进入正确的深层 URL。\n## 约束\n- base 路径是 /vibe_coding_guide/\n- 不更换 Pagefind，不新增登录\n## 验收\n- 输入“API Key”能返回配置课程\n- 点击结果后 URL 仍包含仓库子路径\n- npm test 和浏览器搜索测试通过\n## 不在本次范围\n- 搜索排序重构\n```\n\n## 规格驱动的顺序\n\n1. 人确认用户结果、约束和不做什么；\n2. Agent 读取规格并列出事实与假设；\n3. 人审查计划，特别是架构和依赖决定；\n4. Agent 按小任务实现，把测试映射到验收条目；\n5. 人用结果和证据检查规格是否满足；\n6. 发现新事实时更新规格，而不是只修代码。\n\n<Callout type=\"warning\" title=\"规格不是一次性文档\">\n  代码和规格会一起变化。过时的规格比没有规格更危险，因为 Agent 会自信地执行旧约束。\n</Callout>\n\n功能跨多个模块、有公共接口、需要交接或验收不止是“看起来对”时，值得写规格。小文案和明确常量可以只用 Prompt，但仍要有可观察验收。\n\n<Checklist id=\"methods-spec\" items={[\n  \"规格写清用户结果、约束、验收和不在范围内的事项\",\n  \"我会在人审查规格和计划后才让 Agent 修改\",\n  \"测试用例可以映射回规格中的验收条目\",\n  \"发现新事实时会同步更新规格\"\n]} />\n"},{"path":"lessons/methods/04-harness-engineering.mdx","raw":"---\ntitle: \"Harness Engineering：为 Agent 设计工程环境\"\ndescription: \"把项目规则、工具、权限、测试、日志和恢复机制组织成 Agent 可以可靠工作的环境。\"\nsection: methods\norder: 4\nestimatedMinutes: 14\nprerequisites: [\"会用规格描述功能\"]\noutcomes:\n  - \"识别 Agent Harness 的组成部分\"\n  - \"用项目规则和工具降低重复解释\"\n  - \"为 Agent 设置权限、反馈和恢复边界\"\ntags: [\"Harness Engineering\", \"工具\", \"权限\", \"反馈\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"OpenAI Harness Engineering 官方文章\", \"Anthropic Effective Harnesses 官方文章\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nHarness Engineering 关注 Agent 在什么环境里工作：它能读取什么、使用哪些工具、收到什么反馈、如何判断完成、失败后怎样恢复。OpenAI 将这类工作概括为设计环境、明确意图和建立反馈循环。\n\n## 可借鉴的 Harness 机制\n\n[Claude Code Plugins](https://code.claude.com/docs/en/plugins)、Hooks 和 Permissions 可以组合成一个 Harness：插件提供能力，Hook 在工具调用前后执行确定性检查，权限系统决定哪些动作必须得到人工批准。这里没有一个“万能 Harness Skill”；关键是把工具、反馈、审批和恢复路径组合起来，并且让这些边界可以审计。\n\n## 一个 Harness 包含什么\n\n| 部件 | 项目中的例子 |\n| --- | --- |\n| 任务规范 | `SPEC.md`、Issue、验收清单 |\n| 项目记忆 | `AGENTS.md`、README、架构说明 |\n| 工具接口 | 搜索、编辑、Git、测试命令 |\n| 反馈系统 | 类型检查、单测、E2E、构建日志 |\n| 状态与观测 | 进度文件、Diff、命令输出 |\n| 权限边界 | 工作区、网络、凭证和发布审批 |\n| 恢复机制 | 小提交、worktree、回滚和停止开关 |\n\n项目规则应回答如何安装、测试和构建，哪些文件不能改，何时必须先计划，以及完成后要提供什么证据。规则要短、可执行、经常验证。\n\nAgent 能在几分钟内改几十个文件，不代表应该允许它这么做。一次理想任务应解决一个可命名的问题、修改高度相关的文件、能运行明确检查，并且可整体撤销。\n\n<Callout type=\"warning\" title=\"权限不是体验选项\">\n  删除、发布、发送消息、访问生产数据和读取凭证都应该有明确人工闸门。自动化越强，权限与停止机制越应该写进 Harness。\n</Callout>\n\n<Checklist id=\"methods-harness\" items={[\n  \"我能说出项目 Harness 的规则、工具、反馈和权限边界\",\n  \"项目规则里包含可运行的命令，而不是只有口号\",\n  \"一次任务的 Diff 和回退点都可审查\",\n  \"高风险动作有人工审批和停止机制\"\n]} />\n"},{"path":"lessons/methods/05-loop-engineering.mdx","raw":"---\ntitle: \"Loop Engineering：设计可验证的 Agent 循环\"\ndescription: \"把一次 Prompt 扩展为有触发、状态、验证、停止和人工闸门的可重复 Agent 工作循环。\"\nsection: methods\norder: 5\nestimatedMinutes: 15\nprerequisites: [\"理解 Harness Engineering\"]\noutcomes:\n  - \"区分单次 Prompt、Agent 内部循环和外部工作循环\"\n  - \"为循环写出目标、状态、验证和停止条件\"\n  - \"在失败或无进展时安全恢复，而不是无限重试\"\ntags: [\"Loop Engineering\", \"Ralph Loop\", \"自动化\", \"停止条件\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"IBM Loop Engineering 介绍\", \"Loop Engineering 研究论文\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nLoop Engineering 是一个正在形成的 Agent 工程概念：关注任务怎样发现、执行、观察、验证、记录并安全停止。它不是普通的 `for` 循环，也不是让 Agent 无限制运行。\n\n## 一个可审查的循环\n\n```text\n触发：出现明确 Issue\n目标：修复并验证一个用户可复现的问题\n发现：读取规格、代码、测试和最近 Diff\n行动：在隔离工作区做最小修改\n观察：运行测试、构建或浏览器路径\n判断：证据是否满足验收？\n停止：通过、阻塞、需人工决定，或达到预算/次数上限\n记录：保存状态、命令、结果和剩余风险\n```\n\n## Loop 的五个字段\n\n| 字段 | 问题 |\n| --- | --- |\n| 触发器 | 什么事件允许循环开始？ |\n| 目标 | 最终环境状态必须是什么？ |\n| 验证器 | 哪些测试、评测或人工检查能证明它？ |\n| 停止规则 | 通过、阻塞、超时、预算耗尽时如何停？ |\n| 状态记忆 | 下一次运行如何知道已经做过什么？ |\n\n失败时先写复现卡片，找到第一个非警告错误、对应文件和命令阶段，再要求 Agent 只读分析。不要用递归删除、硬重置或无限重试掩盖不确定性。\n\n## 现在最常被拿来讨论的 Loop Skill\n\n下面这些案例不是“最佳 Skill 排行榜”，而是目前公开资料中最容易看到、也最能说明循环结构的几种实现。它们共同的重点不是让 Agent 多跑几轮，而是让每一轮都留下状态和证据：\n\n| Skill / 工作流 | 循环结构 | 借鉴点 |\n| --- | --- | --- |\n| [Claude Code `/loop`](https://support.claude.com/en/articles/14554000-claude-code-power-user-tips) | 定时触发 → 执行任务 → 检查结果 → 等待下一轮 | 适合周期性检查；先定义频率、幂等性和停止方式 |\n| [Ralph Loop](https://ralph-cli.dev/docs/core-concepts/ralph-loop/) | PRD/任务队列 → 单任务迭代 → 验证与重试 → 持久化进度 | 把“继续做”变成有任务边界、验证命令和会话记忆的循环 |\n| [autoresearch Skill](https://github.com/uditgoenka/autoresearch)（受 [Karpathy autoresearch](https://github.com/karpathy/autoresearch) 启发） | 设定目标与机械指标 → 修改 → 实验/评估 → 保留或回滚 → 继续迭代 | 把“改一点、测一下、只保留更好结果”变成跨 Coding、内容和研究任务的通用循环 |\n\n这些 Skill 可以作为设计参考，但不应直接复制到企业环境。安装前应审查触发条件、脚本和权限；运行时要限制仓库范围、命令集合、次数、预算和网络访问，并保留每轮的测试输出或评测记录。Anthropic 的文档也将 Skill 定位为可按需触发的工作流，而不是每次会话都注入的常驻背景。\n\n<Callout type=\"warning\" title=\"Ralph Loop 不是无限重试\">\n  社区常把反复计划、实现、检查的 Agent 工作方式称为 Ralph Loop。课程只把它作为循环模式的例子：每一轮必须有新证据、退出条件和人工升级路径。\n</Callout>\n\n<Checklist id=\"methods-loop\" items={[\n  \"循环写清触发器、目标、验证器、停止规则和状态记忆\",\n  \"我能区分 Agent 内部循环与外部可调度工作循环\",\n  \"失败时先复现和定位根因，不用无限重试掩盖问题\",\n  \"循环有预算、超时、人工升级和可恢复状态\"\n]} />\n"},{"path":"lessons/methods/06-test-driven-development.mdx","raw":"---\ntitle: \"Test-Driven Development：让测试先成为约束\"\ndescription: \"用失败测试、最小实现和回归检查把 Agent 的生成过程约束在可验证的行为上。\"\nsection: methods\norder: 6\nestimatedMinutes: 14\nprerequisites: [\"会设计 Loop 的验证器\"]\noutcomes:\n  - \"理解 Red-Green-Refactor 在 Agent 协作中的用法\"\n  - \"把需求验收翻译成测试和可观察结果\"\n  - \"避免把测试写成迎合错误实现的装饰\"\ntags: [\"Test-Driven Development\", \"TDD\", \"回归测试\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"经典 TDD 实践\", \"Agent Evals 与代码测试实践\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nTest-Driven Development（TDD）不是让 Agent 多写测试，而是先用一个失败的、可运行的行为约束实现，再用最小修改让它通过，最后在不改变行为的前提下重构。\n\n## 可借鉴的 TDD Skill\n\n[Superpowers 的 `test-driven-development` Skill](https://github.com/obra/superpowers) 把 `RED → GREEN → REFACTOR` 固定成执行顺序，并附带测试反模式说明。它适合学习如何让 Agent 先写失败测试、观察失败，再实现最小改动；实际项目仍需替换成自己的测试命令和验收数据。\n\n## Red → Green → Refactor\n\n1. **Red**：写一个表达需求的失败测试；\n2. **Green**：让 Agent 做最小实现，只处理当前失败；\n3. **Refactor**：测试保持通过，再改善结构；\n4. **回归**：运行受影响区域和完整交付检查。\n\n```text\n需求：搜索结果链接必须保留 /vibe_coding_guide/ 子路径。\nRed：增加点击结果后的 URL 断言。\nGreen：修正统一的 lessonPath 辅助函数。\nRefactor：删除重复的路径拼接逻辑。\n回归：npm test + 浏览器搜索路径测试。\n```\n\nAgent 写测试时，人要确认断言描述的是用户行为，而不是当前实现细节；失败真的能阻止错误实现；边界、错误路径、权限和敏感数据都得到考虑。\n\n<Callout type=\"warning\" title=\"绿色测试不等于正确需求\">\n  Agent 可能修改测试，让错误实现变绿。先审查测试断言，再审查实现；视觉、业务和安全仍需要人工验收。\n</Callout>\n\nTDD 适合稳定、可重复的代码行为；Agent Evals 还要检查多轮工具调用、最终环境状态和轨迹。测试约束局部行为，评测检查完整任务。\n\n<Checklist id=\"methods-tdd\" items={[\n  \"我能用 Red、Green、Refactor 描述一次实现循环\",\n  \"测试断言来自需求和用户行为，而不是迎合当前代码\",\n  \"我会先审查 Agent 生成的测试，再接受实现\",\n  \"自动化测试之外仍保留视觉、业务和安全验收\"\n]} />\n"},{"path":"lessons/methods/07-human-in-the-loop.mdx","raw":"---\ntitle: \"Human-in-the-Loop：把决定权留在人类一侧\"\ndescription: \"为高风险动作设置人工审批、权限边界和升级路径，让 Agent 的自主性始终处在可控制范围内。\"\nsection: methods\norder: 7\nestimatedMinutes: 14\nprerequisites: [\"完成一次测试驱动的实现循环\"]\noutcomes:\n  - \"识别必须由人批准的 Agent 动作\"\n  - \"设计最小权限、审批和停止开关\"\n  - \"处理 Prompt Injection、凭证和供应链风险\"\ntags: [\"Human-in-the-Loop\", \"权限\", \"Prompt Injection\", \"安全\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Anthropic Agent 安全工程文章\", \"Agent Skills 安全建议\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nHuman-in-the-Loop 不是每一步都让人点确认，而是把人的判断放在真正改变风险、责任或业务结果的节点。低风险的搜索、测试和格式化可以自动化；删除、发布、发送消息、访问生产数据和处理凭证必须有人工闸门。\n\n## 可借鉴的人工检查点工作流\n\n[Superpowers 的 `subagent-driven-development` 与 `executing-plans`](https://github.com/obra/superpowers) 将任务拆成批次，在继续下一批前要求人工检查计划符合性、代码质量或关键证据。它们适合作为人工闸门的示例；企业还应结合自己的权限策略，明确哪些文件、命令和外部系统必须人工批准。\n\n## 五个必须保留人工判断的节点\n\n| 节点 | 人要确认什么 |\n| --- | --- |\n| 需求与规格 | 目标、范围和业务含义是否正确 |\n| 权限升级 | Agent 是否真的需要更多权限 |\n| 高风险动作 | 删除、迁移、发布或外发是否获批 |\n| 结果验收 | 测试之外，用户是否得到想要的结果 |\n| 异常升级 | 失败、越权、注入或数据事件由谁接管 |\n\n## 主要风险面\n\n- **Prompt Injection**：外部网页、Issue、README 或依赖文档中的指令不能自动获得信任。\n- **凭证与数据**：Key、Token、SSH 密钥和客户数据不能进入代码、日志、截图或聊天。\n- **软件供应链**：安装模型生成的包前检查来源、维护状态、锁文件和许可证。\n- **过度权限**：工作区写权限、系统写权限和无限网络不是同一级别。\n\n<Callout type=\"warning\" title=\"审批不是信任模型，而是控制影响范围\">\n  即使模型能力很强，也要让每个高风险动作可暂停、可回溯、可撤销。不要用“它通常很可靠”替代权限和审计设计。\n</Callout>\n\n团队基线应包含批准的工具与 Provider、数据分类、默认权限、Skill/MCP 审计、合并与发布门槛、事件响应人和更新后的回归试点。\n\n<Checklist id=\"methods-human\" items={[\n  \"我能指出哪些动作必须人工批准\",\n  \"外部网页、Issue 与 Skill 默认按不可信输入处理\",\n  \"凭证不进入代码、日志、截图和聊天\",\n  \"Agent 有最小权限、停止开关和异常升级路径\",\n  \"发布与生产操作不会因为测试变绿而自动放行\"\n]} />\n"},{"path":"lessons/methods/08-skills-engineering.mdx","raw":"---\ntitle: \"Skills Engineering：把经验封装为可复用能力\"\ndescription: \"把已经验证过的工作方法、脚本和边界写成可发现、可测试、可维护的 Agent Skill。\"\nsection: methods\norder: 8\nestimatedMinutes: 18\nprerequisites: [\"理解 Human-in-the-Loop\", \"完成 Agent Skills 工具课程\"]\noutcomes:\n  - \"判断一段经验是否值得封装成 Skill\"\n  - \"写出触发条件、边界和验证步骤\"\n  - \"用正例、反例和边界请求测试 Skill\"\ntags: [\"Skills Engineering\", \"SKILL.md\", \"复用\", \"工作流沉淀\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"OpenCode Agent Skills 官方文档\", \"Agent Skills 开放规范\", \"GitHub Agent Skills 指南\", \"Every Compound Engineering Plugin\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nSkills Engineering 关注如何把已经验证过的方法和经验封装成 Agent 可以发现、按需加载、反复执行的能力。它不是把所有团队知识写进一个超长 Prompt，也不是把一次偶然成功包装成全局规则。\n\n## 可借鉴的 Skill Engineering 工具\n\nAnthropic 官方目录中的 [`skill-creator`](https://claude.com/plugins/) 用来创建、改进、评估和基准测试 Skill。它本身也是一个很好的元示例：先定义触发条件和评测，再根据失败样例迭代 Skill，而不是只凭一次成功运行判断质量。\n\n## 先写行为合同\n\n| 问题 | 示例：GitHub Pages 发布前检查 |\n| --- | --- |\n| 何时触发？ | 用户要求发布前检查或 Pages 排错时 |\n| 交付什么？ | 通过 / 未通过清单、命令、证据和阻塞原因 |\n| 可以做什么？ | 读取仓库，运行已有检查命令 |\n| 绝不做什么？ | 不部署、不推送、不改文件、不读取密钥 |\n| 怎样算完成？ | 每项检查都有结果或明确阻塞原因 |\n\n## 一个最小的 `SKILL.md`\n\n```md\n---\nname: github-pages-release-check\ndescription: >\n  在请求发布静态站点到 GitHub Pages 前，检查构建、仓库子路径、\n  站内链接和无障碍证据。只读运行，不部署、不推送、不修改文件。\ncompatibility: opencode\nmetadata:\n  scope: project\n  risk: read-only\n---\n\n# GitHub Pages 发布前检查\n\n## 触发条件\n用户要求发布前检查、Pages 排错或确认仓库子路径部署时使用。\n\n## 边界\n- 只操作当前工作树。\n- 不读取或打印密钥和工作区外文件。\n- 不执行部署、推送、提交、删除或改写文件。\n```\n\n正文只保留稳定流程；长规范和错误字典放到 `references/`，机械检查放到 `scripts/`，并写清什么时候读取或运行。脚本要有输入、输出、失败码和最小权限。\n\n## 用三类请求验证 Skill\n\n| 测试 | 输入 | 预期 |\n| --- | --- | --- |\n| 正例 | “发布前检查这个站点能否部署到 GitHub Pages。” | 加载 Skill，只读收集证据 |\n| 反例 | “把首页标题改得更有力。” | 不加载发布检查 Skill |\n| 边界 | “检查完后直接部署。” | 先检查，再说明部署需要授权 |\n\n失败时只改一个假设，然后重跑同一组三个测试。把重复出现且已验证有效的结论沉淀为 Skill、规则、测试或脚本。\n\n<Callout type=\"tip\" title=\"复用不是复制粘贴\">\n  Skill 是可发现、可触发的工作流能力；复盘笔记则是帮助人和 Agent 理解历史决策的持久上下文。\n</Callout>\n\n<Checklist id=\"methods-skills\" items={[\n  \"我已写清 Skill 的触发条件、交付物、权限、禁止项与完成标准\",\n  \"目录名与 frontmatter 中的 name 完全一致\",\n  \"第一个版本范围小、可验证且不含密钥\",\n  \"我用正例、反例和边界请求验证了触发行为\",\n  \"我知道何时把重复代码移入 scripts/\"\n]} />\n"},{"path":"lessons/practice/01-linux-baseline.mdx","raw":"---\ntitle: \"确认你的 Linux 起点\"\ndescription: \"不安装任何东西，先确认发行版、Shell、网络、权限和企业模型信息是否齐全。\"\nsection: practice\norder: 1\nestimatedMinutes: 12\nprerequisites: [\"企业提供一台可使用终端的 Linux 电脑\"]\noutcomes:\n  - \"收集后续安装所需的环境事实\"\n  - \"识别自己是否拥有必要权限\"\n  - \"向管理员一次性索取正确的模型接入信息\"\ntags: [\"Linux\", \"Ubuntu\", \"openEuler\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Ubuntu\", \"openEuler\", \"bash 常用命令\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n打开终端，先不要安装软件。我们要建立一份环境小档案，避免把 Ubuntu 命令复制到 openEuler，或者在没有管理员权限时反复尝试。\n\n## 确认系统与 Shell\n\n```bash\ncat /etc/os-release\nprintf 'shell=%s\\n' \"$SHELL\"\nuname -m\n```\n\n记录以下信息：\n\n- `ID` 与 `VERSION_ID`：发行版和版本；\n- Shell 是否为 `/bin/bash`；\n- 架构是 `x86_64` 还是 `aarch64`。\n\n本教程正文以 Ubuntu + bash 为主。openEuler 通常使用 `dnf` 管理软件包；如果管理员提供的是定制镜像，以企业内部文档优先。\n\n## 检查已有工具\n\n```bash\nfor command in git node npm curl opencode; do\n  if command -v \"$command\" >/dev/null 2>&1; then\n    printf '%-10s %s\\n' \"$command\" \"$(command -v \"$command\")\"\n  else\n    printf '%-10s %s\\n' \"$command\" \"未安装\"\n  fi\ndone\n```\n\n这条命令只检查路径，不会修改电脑。把结果保存到自己的笔记中，不要连同用户名、主机名或内部地址发到公共聊天。\n\n## 确认安装权限\n\n```bash\nsudo -n true 2>/dev/null && echo \"sudo 可用\" || echo \"sudo 需要审批或不可用\"\n```\n\n“需要密码”不代表你应该尝试猜测或绕过。企业电脑没有 sudo 很正常，管理员可能通过软件中心、模块系统或内部安装包提供工具。\n\n<Callout type=\"enterprise\" title=\"向管理员索取五项信息\">\n  模型 Base URL、模型 ID、API Key 获取方式、是否需要代理或企业 CA 证书、接口采用 `/v1/chat/completions` 还是 `/v1/responses`。不要要求管理员把真实密钥发进群聊。\n</Callout>\n\n## 建立安全工作目录\n\n后续实践只在你明确创建的目录内进行：\n\n```bash\nmkdir -p \"$HOME/workspace\"\ncd \"$HOME/workspace\"\npwd\n```\n\n确认输出以你的用户目录开头。不要在 `/`、系统配置目录或共享生产目录里启动 Agent。\n\n<Checklist\n  id=\"practice-linux\"\n  items={[\n    \"我知道自己的发行版、版本、架构和 Shell\",\n    \"我检查了 Git、Node、npm、curl 和 OpenCode 是否已安装\",\n    \"我知道自己是否有 sudo 或需要联系管理员\",\n    \"我已拿到或申请模型接入所需的五项信息\",\n    \"我创建了专用 workspace 目录\"\n  ]}\n/>\n"},{"path":"lessons/practice/02-git-node.mdx","raw":"---\ntitle: \"准备 Git 与 Node.js\"\ndescription: \"安装或验证项目所需的基础工具，并用一个最小 Git 仓库建立可回退的工作起点。\"\nsection: practice\norder: 2\nestimatedMinutes: 16\nprerequisites: [\"已完成 Linux 环境检查\", \"知道软件安装权限\"]\noutcomes:\n  - \"验证 Git、Node.js 与 npm 可用\"\n  - \"配置最小 Git 身份\"\n  - \"创建第一个可回退的仓库基线\"\ntags: [\"Git\", \"Node.js\", \"npm\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Git 官方文档\", \"Node.js LTS\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nGit 负责记录变化和回退；Node.js 与 npm 负责运行网页项目和安装开发依赖。Agent 可以帮你调用它们，但你至少要能判断命令是否成功。\n\n## 安装缺少的工具\n\nUbuntu：\n\n```bash\nsudo apt update\nsudo apt install -y git curl\n```\n\nopenEuler：\n\n```bash\nsudo dnf install -y git curl\n```\n\nNode.js 建议使用企业批准的当前 LTS 版本。若系统仓库版本过旧，不要自行添加来历不明的软件源；优先使用管理员提供的模块、内部镜像或 Node 官方安装方式。\n\n## 验证版本\n\n```bash\ngit --version\nnode --version\nnpm --version\n```\n\n本实践要求 Node.js 22 或企业批准的更新 LTS。看到 `command not found` 时回到安装步骤；看到权限错误时联系管理员。\n\n## 配置 Git 身份\n\n```bash\ngit config --global user.name \"你的姓名\"\ngit config --global user.email \"你的 GitHub 邮箱\"\ngit config --global init.defaultBranch main\n```\n\n检查配置：\n\n```bash\ngit config --global --list\n```\n\n<Callout type=\"note\" title=\"邮箱隐私\">\n  公开仓库可以使用 GitHub 提供的 noreply 邮箱。不要为了跟教程一致而公开企业内部邮箱。\n</Callout>\n\n## 进入当前教程仓库\n\n```bash\ncd \"$HOME/workspace\"\ngit clone https://github.com/MarsChan8293/vibe_coding_guide.git\ncd vibe_coding_guide\ngit status\n```\n\n如果仓库已经存在，直接进入它即可，不要重复克隆。最后应该看到工作区干净；这就是当前项目的第一个安全基线，后续 Agent 修改异常时，可以查看差异或回到最近一次确认的提交。\n\n## 先记住三个 Git 命令\n\n```bash\ngit status\ngit diff\ngit log --oneline --decorate -5\n```\n\n它们分别回答：现在有什么变化、具体改了什么、最近有哪些回退点。\n\n<Checklist\n  id=\"practice-git-node\"\n  items={[\n    \"Git、Node.js 与 npm 都能输出版本\",\n    \"Git 姓名和邮箱配置正确\",\n    \"当前教程仓库已克隆或进入\",\n    \"git status 显示工作区干净\"\n  ]}\n/>\n"},{"path":"lessons/practice/03-install-opencode.mdx","raw":"---\ntitle: \"安装并验证 OpenCode\"\ndescription: \"从官方渠道安装 OpenCode，确认二进制路径和版本，并为企业环境准备最小安全设置。\"\nsection: practice\norder: 3\nestimatedMinutes: 14\nprerequisites: [\"Git、Node.js、npm 可用\", \"拥有安装软件的许可\"]\noutcomes:\n  - \"从批准渠道完成 OpenCode 安装\"\n  - \"确认实际执行的是预期二进制\"\n  - \"知道无外网环境该如何处理\"\ntags: [\"OpenCode\", \"安装\", \"供应链\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"https://opencode.ai/docs/\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n安装 Agent 等于在电脑上加入一个能读取文件和执行命令的程序。来源必须比“能不能装上”更重要。\n\n## 选择安装渠道\n\n如果企业已有内部软件仓库或安装脚本，使用企业渠道。个人可控环境可以按照 OpenCode 官方文档使用安装脚本：\n\n```bash\ncurl -fsSL https://opencode.ai/install | bash\n```\n\n重新打开终端，或按安装输出提示更新 `PATH`。然后验证：\n\n```bash\ncommand -v opencode\nopencode --version\n```\n\n`command -v` 应指向你的用户目录或管理员指定路径，而不是临时下载目录。\n\n<Callout type=\"warning\" title=\"不要盲目执行 curl | bash\">\n  在企业环境中，先确认域名、代理、证书和安装政策。官方命令只是个人环境的便捷路径，不会覆盖组织的供应链要求。\n</Callout>\n\n## 无外网或代理环境\n\n不要关闭证书校验来“解决”下载失败。正确做法是：\n\n1. 向管理员确认代理变量和企业 CA；\n2. 使用内部镜像或离线安装包；\n3. 核对包的版本、来源和校验值；\n4. 将安装步骤记录到团队文档。\n\n常见代理变量由管理员提供：\n\n```bash\nenv | grep -Ei '^(http|https|no)_proxy='\n```\n\n这条命令可能显示内部地址，只在自己的终端检查，不要把输出贴到公共 Issue。\n\n## 第一次启动前\n\n回到练习仓库：\n\n```bash\ncd \"$HOME/workspace/vibe_coding_guide\"\ngit status\n```\n\n确认工作区干净。下一课才会配置模型 API；现在启动后如果要求选择 Provider，可以先退出，不要随便粘贴真实 Key。\n\n<Checklist\n  id=\"practice-install-opencode\"\n  items={[\n    \"安装来源符合企业政策\",\n    \"command -v opencode 指向预期路径\",\n    \"opencode --version 能正常输出\",\n    \"我没有关闭 TLS 校验或使用不明镜像\",\n    \"练习仓库仍保持干净\"\n  ]}\n/>\n"},{"path":"lessons/practice/04-connect-api.mdx","raw":"---\ntitle: \"连接企业模型 API\"\ndescription: \"用环境变量和通用 Provider 模板把 OpenCode 接入企业 OpenAI 兼容接口，不把密钥写进仓库。\"\nsection: practice\norder: 4\nestimatedMinutes: 22\nprerequisites: [\"OpenCode 已安装\", \"管理员已提供模型接入信息\"]\noutcomes:\n  - \"安全设置 Base URL 与 API Key\"\n  - \"配置 OpenAI-compatible 自定义 Provider\"\n  - \"定位认证、模型名和接口类型错误\"\ntags: [\"OpenAI-compatible\", \"API Key\", \"Provider\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst:\n  - \"https://opencode.ai/docs/providers/\"\n  - \"https://opencode.ai/docs/config/\"\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n本教程假设模型服务已经由企业部署。你的工作不是管理 H20、昇腾 910C 或推理框架，而是把管理员提供的接口安全地交给 OpenCode。\n\n## 先在当前终端设置变量\n\n把占位符替换为管理员提供的值，但不要把真实命令复制进聊天记录：\n\n```bash\nexport VIBE_BASE_URL=\"https://gateway.example.invalid/v1\"\nexport VIBE_API_KEY=\"replace-with-secret-from-approved-channel\"\n```\n\n检查变量是否存在，不打印完整内容：\n\n```bash\nprintf 'base_url_set=%s\\n' \"$([ -n \"$VIBE_BASE_URL\" ] && echo yes || echo no)\"\nprintf 'api_key_set=%s\\n' \"$([ -n \"$VIBE_API_KEY\" ] && echo yes || echo no)\"\n```\n\n密钥只对当前终端会话有效。长期保存应使用企业 Secret 工具；不要直接写进 `.bashrc`、README 或项目 `.env` 后提交。\n\n## 创建全局 Provider 配置\n\n打开 `~/.config/opencode/opencode.json`，使用以下模板：\n\n```json\n{\n  \"$schema\": \"https://opencode.ai/config.json\",\n  \"share\": \"disabled\",\n  \"provider\": {\n    \"enterprise\": {\n      \"npm\": \"@ai-sdk/openai-compatible\",\n      \"name\": \"Enterprise Model Gateway\",\n      \"options\": {\n        \"baseURL\": \"{env:VIBE_BASE_URL}\",\n        \"apiKey\": \"{env:VIBE_API_KEY}\"\n      },\n      \"models\": {\n        \"<MODEL_ID>\": {\n          \"name\": \"Enterprise Coding Model\"\n        }\n      }\n    }\n  },\n  \"model\": \"enterprise/<MODEL_ID>\"\n}\n```\n\n将两个 `<MODEL_ID>` 替换为管理员给出的精确模型 ID。保留引号。\n\n<Callout type=\"enterprise\" title=\"接口类型要匹配\">\n  `/v1/chat/completions` 类接口使用 `@ai-sdk/openai-compatible`。若管理员明确说明只支持 `/v1/responses`，应按 OpenCode 官方文档改用 `@ai-sdk/openai`。不要靠反复试错猜接口。\n</Callout>\n\n## 启动并确认模型\n\n```bash\ncd \"$HOME/workspace/vibe_coding_guide\"\nopencode\n```\n\n在 OpenCode 中打开模型列表，确认能看到 `Enterprise Model Gateway` 和你的模型。先发送一个无敏感信息的测试：\n\n```text\n只回复：连接成功。不要读取或修改任何文件。\n```\n\n然后退出，检查仓库：\n\n```bash\ngit status\n```\n\n应该没有新修改。\n\n## 三类常见错误\n\n### 401 或 403\n\nKey 缺失、过期、权限不足，或网关要求自定义 Header。不要把 Key 打印出来；重新通过批准渠道获取。\n\n### 404 或 Route not found\n\nBase URL 缺少 `/v1`、多了一段路径，或者 SDK 与接口类型不匹配。\n\n### Model not found\n\n`models` 中的键与网关真实模型 ID 不一致。显示名称可以自定义，模型 ID 必须精确。\n\n<Callout type=\"warning\" title=\"发现泄露立即轮换\">\n  如果真实 Key 出现在 Git、截图、终端录屏或公共聊天中，不要只删除消息。立即联系管理员撤销并生成新 Key，再检查是否已被使用。\n</Callout>\n\n<Checklist\n  id=\"practice-api\"\n  items={[\n    \"Base URL 和 API Key 只通过环境变量提供\",\n    \"OpenCode 配置中没有真实密钥\",\n    \"Provider 使用与接口匹配的 AI SDK 包\",\n    \"模型列表能看到企业模型\",\n    \"无文件读取测试成功且 git status 仍干净\"\n  ]}\n/>\n"},{"path":"lessons/practice/05-first-session.mdx","raw":"---\ntitle: \"完成第一次安全会话\"\ndescription: \"认识 Plan、文件引用与会话命令，让 OpenCode 先观察、再计划、最后做一个可验证的小修改。\"\nsection: practice\norder: 5\nestimatedMinutes: 22\nprerequisites: [\"企业 Provider 连接成功\", \"练习仓库工作区干净\"]\noutcomes:\n  - \"识别 OpenCode 的高频命令与输入语法\"\n  - \"把目标、范围和验收标准写进任务\"\n  - \"先使用只读探索，再授权修改\"\n  - \"用 Git Diff 与命令结果验证交付\"\ntags: [\"首次会话\", \"Plan\", \"常用命令\", \"Git Diff\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"OpenCode TUI 官方文档\", \"OpenCode Rules 官方文档\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n第一次会话不做完整网站。我们只让 Agent 改进 README，并观察从指令到证据的整个过程。\n\n## 先认识高频命令与输入语法\n\nOpenCode 的斜杠命令用于控制会话；`@` 和 `!` 则把文件或命令结果带进当前上下文。先记住下面这些，不需要一次全部使用：\n\n| 输入 | 作用 | 什么时候用 |\n| --- | --- | --- |\n| `Tab` 切到 **Plan** | 切换到只读规划 Agent | 大改动前先探索、比较方案，不授权编辑 |\n| `/init` | 扫描仓库并创建或更新 `AGENTS.md` | 建立项目长期规则；下一课再实际执行 |\n| `@README.md` | 精确引用文件并加入当前上下文 | 明确告诉 Agent 应重点阅读什么 |\n| `!git status` | 直接运行 Shell，并把输出加入会话 | 快速提供仓库状态、测试或诊断证据 |\n| `/compact` | 总结当前长会话，释放上下文空间 | 任务仍要继续，但对话已经很长 |\n| `/new` | 开始一个空白新会话；别名是 `/clear` | 当前任务已经结束，要切换到新目标 |\n| `/sessions` | 查看并恢复旧会话；别名是 `/resume` | 回到之前尚未结束的任务 |\n| `/models` | 查看和选择可用模型 | Provider 已连接，需要切换模型时 |\n| `/undo`、`/redo` | 撤销或重做最近一轮消息及文件改动 | Agent 改错且仓库处于 Git 管理下 |\n| `/help` | 打开当前版本的帮助 | 忘记命令或快捷键时 |\n\n<Callout type=\"note\" title=\"Plan 不是斜杠命令\">\n  OpenCode 内置的 Plan 与 Build 是两种主 Agent。默认用 `Tab` 切换；看到状态栏已显示 Plan 后，再开始只读探索。不同工具可能把类似能力叫作 Plan mode 或 `/plan`，不要把其他产品的命令直接照搬到 OpenCode。\n</Callout>\n\n命令和快捷键会随版本变化。使用前可在 `/help` 中确认，也可核对 [OpenCode TUI 官方文档](https://opencode.ai/docs/tui/)。\n\n## 第一步：只读探索\n\n在仓库中启动 OpenCode：\n\n```bash\ncd \"$HOME/workspace/vibe_coding_guide\"\nopencode\n```\n\n按 `Tab` 切换到 **Plan**，然后输入：\n\n```text\n先不要修改文件。\n请检查当前仓库结构、@README.md 和 Git 状态，然后说明：\n1. 这个项目现在有什么；\n2. 下一步最小、可验证的改进是什么；\n3. 你准备读取和修改哪些文件。\n```\n\n好的回复应该承认仓库几乎为空，并把范围限制在 README。若它声称看到了不存在的文件，先指出事实，不要继续授权。\n\n你也可以直接输入 `!git status`，把未经模型转述的 Git 输出加入会话。它适合补充证据，但不能替代你最后在独立终端中的人工核对。\n\n## 第二步：给出完整任务\n\n```text\n目标：把 README 改成当前 Vibe Coding 教程项目说明。\n范围：只允许修改 README.md，不创建其他文件，不安装依赖。\n内容：教程目标、课程结构、技术约束、完成定义。\n验收：\n1. Markdown 结构清晰；\n2. 不包含真实姓名、密钥或内部地址；\n3. 修改后展示 git diff；\n4. 不执行 git commit。\n请先给出 3 步计划，等我确认后再修改。\n```\n\n先阅读计划。只有计划符合范围，才回复“按计划执行”。\n\n## 第三步：自己查看证据\n\n退出或另开终端：\n\n```bash\ngit status\ngit diff -- README.md\n```\n\n逐行检查：\n\n- 只修改了 README；\n- 内容符合目标；\n- 没有虚构已经完成的网站功能；\n- 没有敏感信息。\n\n如果不满意，不要只说“再好一点”。指出具体差异，例如“完成定义必须写成可勾选的四项，并删除没有证据的完成描述”。\n\n## 第四步：接受并提交\n\n确认内容后：\n\n```bash\ngit add README.md\ngit commit -m \"Clarify tutorial project README\"\ngit status\n```\n\n<Callout type=\"checkpoint\" title=\"你刚完成了完整闭环\">\n  观察事实 → 写清任务 → 审查计划 → 授权修改 → 查看 Diff → 人工提交。后面的项目会更复杂，但循环不变。\n</Callout>\n\n## 任务结束后怎样处理会话\n\n- 任务还没结束、但上下文已经很长：使用 `/compact`；\n- README 任务已结束，准备开始无关任务：使用 `/new`；\n- 以后想回到这次会话：使用 `/sessions` 或 `/resume`；\n- Agent 最近一轮修改方向完全错误：先检查 `git diff`，再决定是否使用 `/undo`。\n\n不要把 `/compact` 当成新会话：它保留任务连续性，只压缩历史。也不要把 `/new` 当成删除记录：旧会话仍可从会话列表恢复。\n\n## 如果 Agent 越界\n\n先停止当前动作，再用 `git status` 和 `git diff` 确认影响。不要立刻运行 Agent 建议的清理命令。如果只有未提交文件修改，可以逐个决定保留或恢复；涉及安装、网络或系统文件时，记录命令并联系管理员。\n\n<Checklist\n  id=\"practice-first-session\"\n  items={[\n    \"我能说出 Plan、/init、/compact、/new 和 @文件引用的作用\",\n    \"Agent 在修改前先完成了只读探索\",\n    \"任务包含目标、范围和验收标准\",\n    \"计划得到人工确认后才执行\",\n    \"git diff 只包含 README.md\",\n    \"我本人确认内容后才创建 Git 提交\"\n  ]}\n/>\n"},{"path":"lessons/practice/06-agent-rules.mdx","raw":"---\ntitle: \"编写项目规则：AGENTS.md\"\ndescription: \"以本项目的 AGENTS.md 为例，把全局协作边界、验证流程和发布权限写成 Agent 能遵守的仓库规则。\"\nsection: practice\norder: 6\nestimatedMinutes: 18\nprerequisites: [\"完成第一次安全会话\", \"知道项目需要哪些验证命令\"]\noutcomes:\n  - \"区分项目常驻规则与一次性 Prompt、规格和 Skill\"\n  - \"写出短小、可执行、可审查的 AGENTS.md\"\n  - \"为验证流程和发布权限设置明确边界\"\ntags: [\"AGENTS.md\", \"项目规则\", \"Harness\"]\nreviewedAt: \"2026-07-26\"\nreviewedAgainst: [\"本项目 AGENTS.md\", \"OpenCode Rules 官方文档\", \"Agent Harness 工程实践\"]\ndraft: false\n---\n\nimport Checklist from \"../../../components/Checklist.astro\";\n\n项目规则文件解决的是一个具体问题：每次启动 Agent，都不必重新解释那些始终有效的协作边界。它不是一份巨大的 Prompt，也不是把所有任务步骤都提前写死。\n\n## 用 `/init` 生成可审查的初稿\n\n在仓库中启动 OpenCode，确认当前工作区状态后运行：\n\n```text\n/init\n```\n\nOpenCode 会扫描仓库中的重要文件，创建或更新 `AGENTS.md`。它通常会提取构建、测试、目录结构和项目约定，但生成结果只是**初稿**，不是自动生效的企业政策。\n\n运行后先检查：\n\n```bash\ngit diff -- AGENTS.md\n```\n\n删除无法从仓库验证的推测，补上明确的验证顺序和发布边界，再决定是否提交。若仓库已有 `AGENTS.md`，`/init` 可能更新原文件，因此运行前必须先看 `git status`。具体行为以 [OpenCode Rules 官方文档](https://opencode.ai/docs/rules/)为准。\n\n## 先判断什么值得常驻\n\n适合写入 `AGENTS.md` 的内容通常满足三个条件：适用于大多数任务、能通过命令或文件状态检查、违反后会造成明显损失。例如验证命令、目录约定、权限边界和不可触碰的数据。\n\n一次性的页面需求、某个 Issue 的验收标准和只在特定任务触发的复杂流程，应分别放进 Prompt、规格文件或 Skill。\n\n## 以当前项目的 `AGENTS.md` 为例\n\n本项目的 [AGENTS.md](https://github.com/MarsChan8293/vibe_coding_guide/blob/main/AGENTS.md) 只有两组核心规则：\n\n| 规则组 | 文件中的约定 | 为什么常驻 |\n| --- | --- | --- |\n| 修改后验证 | 先运行 `npm test`，再运行 `npm run dev`；只有布局、样式、组件或交互改动才需要浏览器检查 | 每次修改都适用，而且结果可以被命令和人工检查验证 |\n| 发布边界 | 未明确要求时，不执行 `git push`、Pull Request、推送 `main` 或 GitHub Pages 部署 | 保护远程仓库和公开站点，必须在每次协作中保持一致 |\n\n这比“请 Agent 小心一点”更有用，因为它给出了顺序、例外、触发条件和禁止动作。\n\n## 写完之后做四项审查\n\n1. 这条规则是否适用于几乎所有任务，而不是只适用于一个页面？\n2. Agent 能否通过命令、Diff 或文件状态判断自己是否遵守？\n3. 是否明确了需要人工决定的边界？\n4. 是否与团队批准的工具、命令和发布流程一致？\n\n如果一条规则只对当前任务有用，就把它移回任务 Prompt 或规格；如果它需要复杂步骤、脚本和独立验证，就考虑封装为 Skill。保持 `AGENTS.md` 短小，规则才容易被持续读取和维护。\n\n<Checklist id=\"practice-agent-rules\" items={[\n  \"我运行 /init 后先审查了 AGENTS.md 的 Diff\",\n  \"我能区分 AGENTS.md、Prompt、规格和 Skill 的作用域\",\n  \"我写出了验证命令和发布边界\",\n  \"每条规则都能被观察或检查\",\n  \"规则没有混入某个单次任务的细节\"\n]} />\n"},{"path":"lessons/practice/06-portfolio-brief.mdx","raw":"---\ntitle: \"与AI进行项目需求沟通\"\ndescription: \"复盘当前教程项目与 AI 的真实需求沟通过程：先用 grill-me 追问，再把确认过的范围、取舍和验收标准交给 Agent 执行。\"\nsection: practice\norder: 8\nestimatedMinutes: 20\nprerequisites: [\"已完成第一次项目规则编写\", \"已安装并验证 grill-me\"]\noutcomes:\n  - \"使用 grill-me 把模糊想法逐轮收敛成明确决策\"\n  - \"区分已确认、待决定和明确排除的内容\"\n  - \"用对话记录、任务清单和 Git diff 验证需求是否落地\"\ntags: [\"需求沟通\", \"grill-me\", \"范围管理\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Web 内容与设计基本实践\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nAgent 最容易生成的是一个“看起来像教程”的网站。真正困难的是先把范围、取舍和验收方式说清楚。本章不额外创建没有实例的需求文档，而是复盘这个项目实际发生的需求沟通：你提出方向，`grill-me` 追问，双方逐轮确认，Agent 再按确认结果修改页面。\n\n## 第一步：从一句想法开始\n\n最初的需求是：构建一个面向企业零基础用户的中文 Vibe Coding 教程网站，使用 Astro、MDX 和 TypeScript，部署到 GitHub Pages，并分成历史、工具、实践和方法几个部分。\n\n这时仍有很多未知项：历史写多长、工具讲哪些、实践用什么主线、方法是否引用社区概念、哪些内容必须删掉。没有直接让 Agent 开始写页面，而是先安装并使用 `grill-me`，要求它连续提问、等待回答，不替用户补全未确认的决定。\n\n## 第二步：用追问收敛历史范围\n\n沟通先解决“历史写什么”。经过几轮确认，范围从泛泛的行业发展收敛为：从 2025 年开始，用少量时间轴讲清模型发布、Coding Agent、Skills、长期运行 Agent 和 Agentic Engineering 的演进。\n\n随后又把时间轴调整为双轨：左侧是模型发布，右侧是 AI 工具和 Agent 工作方式。具体排除了模型训练史、融资新闻和每个小版本；时间点按真实发布日期排列，两侧可以错开，不为了排版强行配对。这个决定直接影响了历史页的结构和每张卡片的文案。\n\n## 第三步：明确模型与工具边界\n\n工具部分不是“把所有热门产品列一遍”，而是先确定模型范围：国外闭源只讲 Claude、OpenAI 和 Gemini；中国开放权重只讲 DeepSeek、GLM 和 Kimi。实践主线采用 Linux、企业提供的 OpenAI 兼容 API 和 OpenCode。\n\n沟通中还明确了几项排除项：不讲云端 Agent 章节，不保留企业选型章节，OpenCode 放在终端 Agent 后面；工具地图只保留模型、编辑器型工具、终端 Agent、OpenCode 和 Skills 等实际需要的内容。这样，Agent 的任务不再是“介绍工具”，而是按已确认的边界重排目录、修改标题并删除多余页面。\n\n## 第四步：把方法变成课程\n\n方法部分也经过了对齐，而不是由 Agent 自行发明。最终保留八个工程方法：Prompt Engineering、Context Engineering、Spec-Driven Development、Harness Engineering、Loop Engineering、Test-Driven Development、Human-in-the-Loop 和 Skills Engineering，并补充社区中实际流行的 `grill-me`、`autoresearch` 等 Skill 示例。\n\n每个方法先讨论“是否适合本教程”和“有没有可引用的 Skill 或 Plugin”，确认后才写入页面。比如 Loop Engineering 的示例替换为 `autoresearch`，而不是把未经确认的工具硬塞进课程。\n\n## 第五步：根据反馈持续改版\n\n真实沟通不会在第一次回答后结束。本项目后来又根据页面检查结果做了多轮小步修改：\n\n- 将导航统一为“历史回顾、工具介绍、入门教程、工程方法、实践案例”；\n- 单独增加“编写项目规则 AGENT.md”章节，并把当前项目的规则作为实例；\n- 将 `grill-me` 作为第一个 Skill，在 `skills.sh` 搜索并安装；\n- 删除 GitHub Pages、移动端无障碍等不属于当前入门路径的章节；\n- 合并生成、迭代、测试审查相关内容，保持课程顺序连续；\n- 看到不准确的模型名称或多余提示语时，直接提出具体删除或替换要求。\n\n每次修改都先确认“改什么”，再让 Agent 执行，最后用测试、构建和页面内容检查验证结果。需求的真实产物不是一份从未创建的文档，而是对话中的已确认结论、仓库里的 MDX、Git diff 和通过的构建结果。\n\n<Callout type=\"warning\" title=\"把对话当作需求过程，而不是一次性提示词\">\n  不要让 Agent 根据一句“做一个教程网站”自行决定全部内容。先让 `grill-me` 追问范围、读者、保留项、删除项、技术边界和验收证据；每轮回答后再继续。涉及公开发布时，仍要排除客户机密、内部地址、真实密钥和未公开项目资料。\n</Callout>\n\n## 可以复用的沟通模板\n\n在任何已有项目中，可以从下面这段话开始：\n\n```text\n使用 grill-me，先不要修改文件。\n请先通过连续追问帮我明确：\n1. 这次改动服务谁，解决什么问题；\n2. 哪些页面、功能和文字必须保留；\n3. 哪些内容要删除、合并或改名；\n4. 技术、视觉、发布和安全边界是什么；\n5. 最终用什么测试、页面检查或用户反馈验收。\n每次只问必要的问题，等我回答后再继续；不要替我猜测未确认的需求。\n```\n\n沟通结束后，让 Agent 先复述“已确认 / 待决定 / 明确排除”三栏，再执行修改。这样可以在不额外创建需求文档的情况下，保留清晰的决策链，并让后续的 diff 和测试结果都能回溯到具体讨论。\n\n<Checklist\n  id=\"practice-communication\"\n  items={[\n    \"能说明本项目最初需求如何从模糊想法开始\",\n    \"能区分历史、模型、工具和方法部分已经确认的范围\",\n    \"能说出至少一项明确删除或合并的内容及原因\",\n    \"能用 grill-me 模板让 Agent 先追问、后执行\",\n    \"能用 MDX、Git diff 和测试结果验证需求已经落地\"\n  ]}\n/>\n"},{"path":"lessons/practice/07-task-breakdown.mdx","raw":"---\ntitle: \"拆解、生成与验证当前项目\"\ndescription: \"以 vibe_coding_guide 的实际改版为例，把需求拆成可回滚的小任务，再用内容校验、构建和页面检查验证每一轮结果。\"\nsection: practice\norder: 9\nestimatedMinutes: 32\nprerequisites: [\"完成与 AI 的项目需求沟通\", \"项目规则与目录范围已经确认\"]\noutcomes:\n  - \"把一次教程改版拆成有顺序、有限文件范围的任务\"\n  - \"让 Agent 先生成计划，再按轮次修改当前仓库\"\n  - \"用测试、构建、页面和 Git diff 证实结果，而不是只听 Agent 宣布完成\"\ntags: [\"计划\", \"任务拆解\", \"生成\", \"验证\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst: [\"Agentic Coding 常用任务拆解实践\"]\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\n“改完整个教程网站”太大。Agent 可能同时决定内容、导航、样式和发布，任何一步偏离都难以定位。本章直接复盘 `vibe_coding_guide` 的改版过程：怎样盘点现状，怎样把需求拆成小轮次，怎样让 Agent 生成内容，以及怎样用测试和页面证据验收。\n\n## 第一步：先盘点当前仓库\n\n在让 Agent 修改前，先让它读取项目规则、README、课程目录和测试，不要急着生成代码：\n\n```text\n请先阅读 AGENTS.md、README.md、src/content/lessons/、src/pages/ 和 tests/。\n现在不要修改文件。\n请列出：\n1. 当前历史、工具、实践、方法各有多少篇；\n2. 每篇课程的路由、order 和前置依赖；\n3. 导航、总课数、校验脚本和测试分别在哪里；\n4. 本轮需求会影响哪些文件；\n5. 哪些内容目前没有实例，不能凭空补写。\n```\n\n本项目的盘点结果是：1 篇历史、8 篇工具、9 篇实践和 8 篇方法。这个数字不是写在提示词里的目标，而是由 `src/content/lessons/` 和 `scripts/validate-content.mjs` 共同约束的事实。先读现状，才能避免把已经删除的章节重新生成出来。\n\n## 第二步：把本轮改版拆成任务\n\n结合上一章已经确认的范围，可以把本项目的修改拆成以下轮次：\n\n1. **历史轮**：调整 2025 年至今的模型发布与 Agent 工具双轨时间轴，按真实时间错开卡片；\n2. **工具轮**：限定 Claude、OpenAI、Gemini、DeepSeek、GLM、Kimi 的模型范围，调整 OpenCode 与终端 Agent 的顺序；\n3. **实践轮**：增加当前项目的 `AGENTS.md` 编写和 `grill-me` 安装，删除不需要的章节，合并生成与验证内容；\n4. **方法轮**：补充八个已经确认的工程方法和对应的 Skill / Plugin 示例；\n5. **一致性轮**：同步课程 order、侧栏标题、导航名称、总数校验和站内测试；\n6. **验收轮**：运行完整测试、生产构建、Pagefind 和链接检查，再检查受影响页面。\n\n每轮都写清楚目标、文件范围和验收证据。例如实践轮只改 `src/content/lessons/practice/`、校验脚本和相关测试，不顺手重做全站样式。这样某一轮失败时，可以准确判断是内容、目录还是构建问题。\n\n## 第三步：先让 Agent 复述计划\n\n可以把当前轮次交给 Agent，但要求它先给计划：\n\n```text\n基于刚才的仓库盘点，只处理“实践轮”。\n先不要修改文件，请先列出：\n- 要新增、修改、删除的具体文件；\n- 每个文件要解决的一个问题；\n- 课程顺序和总数会如何变化；\n- 修改后运行哪些验证命令；\n- 哪些决定仍需要我确认。\n等我确认计划后再开始。\n```\n\n计划中如果出现“优化所有页面”“完善用户体验”“必要时重构”等无法验收的句子，就继续追问。好的任务应该能回答：改哪个文件、改到什么状态、用什么证据证明完成。\n\n## 第四步：按小轮次生成和修改\n\n本项目的实践轮可以这样执行：\n\n```text\n现在只完成已确认的实践轮：\n1. 新增 practice/06-agent-rules.mdx，内容以当前 AGENTS.md 为实例；\n2. 将 practice/06-portfolio-brief.mdx 改为“与AI进行项目需求沟通”，复盘真实的 grill-me 过程；\n3. 将 practice/07-task-breakdown.mdx 改为当前仓库案例；\n4. 将 grill-me 安装章节放在需求沟通之前；\n5. 删除已经确认不需要的章节并重新编号。\n不要修改工具、历史、方法或样式文件。完成后先展示 diff 摘要。\n```\n\n每轮修改后先看范围：\n\n```bash\ngit diff --stat\ngit status --short\ngit diff -- src/content/lessons/practice src/lib/site.ts scripts/validate-content.mjs tests/site.spec.ts\n```\n\n如果发现 Agent 顺手改了不在范围内的文件，先回退这部分或要求它解释原因；不要因为页面“看起来更完整”就接受未经确认的扩展。\n\n## 第五步：用证据验证生成结果\n\n本项目的内容、类型和生产产物由同一条命令验证：\n\n```bash\nnpm test\n```\n\n它会依次检查：\n\n- 课程数量、section、frontmatter、草稿状态、密钥和内网地址；\n- Astro / TypeScript 诊断；\n- 生产构建、Pagefind 中文索引和站内链接、静态资源解析。\n\n命令通过后再启动本地服务：\n\n```bash\nnpm run dev\n```\n\n涉及布局、样式、组件、交互、响应式或资源路径时，还要打开受影响页面检查；纯文案或 MDX 元数据修改只需完成测试和本地服务启动。无论是否打开浏览器，都不能把“Agent 说完成了”当作验收证据。\n\n<Callout type=\"note\" title=\"验证的是需求，不只是代码能构建\">\n  构建成功只能证明 Astro 能生成页面。还要对照已经确认的需求检查：历史是否从 2025 年开始、模型范围是否正确、工具和实践顺序是否正确、删除的章节是否真的消失、导航标题是否统一，以及当前页面是否仍有真实实例。\n</Callout>\n\n## 第六步：阅读最终 Diff\n\n验收最后回到仓库事实：\n\n```bash\ngit diff --stat\ngit diff -- src/content/lessons/history src/content/lessons/tools src/content/lessons/practice src/content/lessons/methods\ngit status --short\n```\n\n重点检查：\n\n- 新增内容是否来自已经确认的对话，而不是 Agent 自行编造；\n- 删除和合并是否反映真实需求；\n- 课程 order、侧栏、首页和总数校验是否一致；\n- 没有真实 API Key、客户内部地址或未授权发布动作；\n- 测试失败时是否保留了可定位的错误，而不是绕过校验。\n\n本项目的计划留在对话和任务拆解中，实际可回溯的产物是 MDX、校验脚本、测试结果和 Git diff，不需要额外创建没有实例的计划文档。提交、推送和 GitHub Pages 发布也必须等用户明确授权。\n\n<Checklist\n  id=\"practice-project-loop\"\n  items={[\n    \"先盘点当前仓库和课程数量，再开始修改\",\n    \"每轮任务都有明确的文件范围和验收证据\",\n    \"Agent 先复述计划，未确认的扩展没有被执行\",\n    \"npm test 和 npm run dev 都已完成\",\n    \"我亲自阅读了最终 Diff，并核对删除、合并和顺序变化\"\n  ]}\n/>\n"},{"path":"lessons/practice/11-install-skill.mdx","raw":"---\ntitle: \"安装并验证第一个 Skill：grill-me\"\ndescription: \"从 skills.sh 搜索并安装 grill-me，验证它如何通过连续追问帮助当前项目澄清需求。\"\nsection: practice\norder: 7\nestimatedMinutes: 22\nprerequisites: [\"完成第一次项目规则编写\", \"理解 Skill 的作用域与审计方法\"]\noutcomes:\n  - \"从 skills.sh 找到并安装 grill-me\"\n  - \"在安装前检查来源、内容与权限边界\"\n  - \"用正例和越界请求验证 Skill\"\ntags: [\"Agent Skills\", \"grill-me\", \"安装\", \"供应链\", \"OpenCode\"]\nreviewedAt: \"2026-07-25\"\nreviewedAgainst:\n  - \"https://opencode.ai/docs/skills/\"\n  - \"Agent Skills 开放规范\"\ndraft: false\n---\n\nimport Callout from \"../../../components/Callout.astro\";\nimport Checklist from \"../../../components/Checklist.astro\";\n\nOpenCode 不需要单独的 Skill 插件。所谓“安装”，就是把一个经过审计的 Skill 目录放进它会发现的位置。本课从 [skills.sh](https://www.skills.sh/mattpocock/skills/grill-me) 搜索 `grill-me`，再安装到当前项目，用它为后面的需求沟通做准备。\n\n## 第一步：确认安装目标\n\nOpenCode 会从下面的路径发现项目级 Skill：\n\n```text\n.opencode/skills/<skill-name>/SKILL.md\n```\n\n这次使用 `grill-me`。它的作用是通过系统性追问压力测试计划和设计，不替你写代码，也不应自动获得提交、推送或部署权限。\n\n<Callout type=\"warning\" title=\"先审计，后复制\">\n  不要对陌生 Skill 使用“一键安装”命令。先查看 `SKILL.md`、它引用的文件和全部脚本；确认来源、权限、网络访问与撤销方式后，再把目录复制进项目。\n</Callout>\n\n## 第二步：审计准备安装的内容\n\n在管理员批准的临时目录中打开 `SKILL.md`，逐项确认：\n\n- `name` 与目录名完全一致；\n- `description` 只在需求澄清和方案审查时触发；\n- 没有要求读取密钥、环境变量值或工作区外文件；\n- 没有修改、删除、提交、推送或部署动作；\n- 没有未审查的脚本、依赖和外部连接。\n\n## 第三步：在 skills.sh 搜索并安装\n\n打开 [skills.sh 的 grill-me 页面](https://www.skills.sh/mattpocock/skills/grill-me)，确认名称、仓库和用途后，在当前项目根目录执行：\n\n```bash\nnpx skills add https://github.com/mattpocock/skills --skill grill-me\n```\n\n安装器可能会询问目标 Agent 和作用域。初次练习选择当前项目或用户级目录，并记录实际安装路径；不要在没有阅读内容前接受扩大权限的选项。\n\n## 第四步：审计 `SKILL.md`\n\n找到安装后的 `grill-me` 目录，先完整阅读 `SKILL.md`。页面目前给出的核心内容是：\n\n```md\n---\nname: grill-me\ndescription: >\n  Relentless interviewing skill that stress-tests plans and designs through systematic questioning.\n---\n\n# grill-me\n\nRun a `/grilling` session.\n```\n\n它的重点是提问，不是执行命令。即使 Skill 内容很短，也要确认它没有额外脚本、网络访问或隐藏权限。\n\n`grill-me` 来自 `mattpocock/skills`，skills.sh 页面显示它用于设计审查、架构验证和实施前规划，并提供安全审计入口。第三方 Skill 仍需记录仓库地址、版本、审计日期和撤销方式。\n\n## 第五步：让 OpenCode 发现并运行\n\n如果 OpenCode 已经在运行，退出当前会话，再从当前教程仓库根目录重新启动：\n\n```bash\nopencode\n```\n\n在当前项目根目录启动 OpenCode，输入一个正例：\n\n```text\n请使用 grill-me，先通过连续提问帮我澄清这个项目下一轮内容改版的目标、受众、范围、验收标准和发布边界。先提问，不修改文件。\n```\n\n你应该看到 OpenCode 加载这个 Skill，并进入 `/grilling` 会话。如果提示找不到，依次检查：\n\n1. 文件名是否严格为 `SKILL.md`；\n2. 目录名与 frontmatter 的 `name` 是否都是 `grill-me`；\n3. OpenCode 是否从当前 Git 工作树内启动；\n4. `opencode.json` 是否把该 Skill 的权限设为 `deny`。\n\n## 第六步：测试边界并留下记录\n\n再输入一个越界请求：\n\n```text\n完成提问后直接替我提交、推送并部署。\n```\n\nSkill 应把这些动作留给明确授权，而不是把“需求澄清”扩张成“执行发布”。记录它提出的关键问题和你的决定；确认安装范围无误后，再由你决定是否提交 Skill 文件：\n\n```bash\ngit status --short\ngit diff -- .agents/skills .claude/skills .opencode/skills\ngit status\n```\n\n<Callout type=\"checkpoint\" title=\"现在它才算安装完成\">\n  文件已经进入可追踪的 Skill 目录、OpenCode 能发现它、提问行为与越界行为都经过验证，并且安装来源和撤销方式有记录。\n</Callout>\n\n<Checklist\n  id=\"practice-install-skill\"\n  items={[\n    \"我从 skills.sh 找到了 mattpocock/skills 的 grill-me\",\n    \"我在安装前完整阅读了 SKILL.md 及其引用内容\",\n    \"OpenCode 能在正例请求中加载并运行 grill-me\",\n    \"grill-me 会先提问，不会擅自修改文件\",\n    \"Skill 面对提交、推送和部署请求时保持了权限边界\",\n    \"安装来源、版本和撤销方式可以追溯\"\n  ]}\n/>\n"}];
